INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Jeep Compass candidata al premio Volante d’Oro 2017 di Autobild',
  'jeep-compass-candidata-al-premio-volante-d-oro-2017-autobild',
  'Noleggia subito la tua Jeep Compass!',
  '## IL SUV più amato dagli italiani e dagli europei è candidato al premio Volante d''Oro 2017. Ecco perché la nuova Jeep Compass merita di vincere.

Oltre all’[Alfa Romeo Stelvio](https://www.nolosubito.it/novita-sul-noleggio-lungo-termine/alfa-romeo-stelvio-volante-d-oro-2017/) e alle due Ferrari 812 Superfast e GTC4 Lusso T, c’è un’altra creatura di casa Fiat Chrysler Automobiles candidata alla vincita del premio Volante d’Oro della rivista tedesca Atobild, uno dei riconoscimenti più ambiti del settore automotive.

Si tratta della [nuova Jeep Compass](https://www.nolosubito.it/novita-sul-noleggio-lungo-termine/nuova-jeep-compass-sara-lauto-piu-venduta-europa/), che compare in lizza nella sua categoria di appartenenza, ossia **SUV di dimensioni compatte**, in cui dovrà sfidare 11 concorrenti.

A breve saranno comunicate le **25 finaliste**, dalle 42 presenti in tutte le categorie in gara, mentre le auto vincitrici di ogni categoria si conosceranno solo il prossimo 7 novembre durante una cerimonia organizzata dal celebre magazine tedesco e dopo un test che si terrà sulla pista del Balocco in Italia, dove saranno provate da una giuria di 6 esperti. Saranno, infine, **i lettori di Autobild a decidere chi meriterà il premio Volante d’Oro** attraverso un sistema di votazione online.
### **Le concorrenti della Jeep Compass**

12 saranno le vetture che si sfideranno per la categoria** “SUV di dimensioni compatte”** e quindi 11 saranno gli avversari della Jeep Compass. Tre le concorrenti più temute, Skoda Karoq, Mitsubishi Eclipse Cross e Mini Countryman, mentre, per i SUV più piccoli ci sono la Hyundai Kona, la Kia Stonic, la Seat Arona, le nuove Citroen C3 Aircross e Opel Crossland X, la Toyota C-HR, la Volkswagen T-Roc e la nuova Suzuki Ignis, che al momento rappresenta il SUV più piccolo in vendita nel mercato europeo.
### **Perché la Jeep Compass potrebbe vincere il Volante d’Oro?**

**La Jeep Compass ha ottime probabilità di vittoria** e di sbaragliare la concorrenza perché ha delle caratteristiche uniche e appetibili soprattutto per quanto riguarda la sua categoria di appartenenza e perché è considerato un SUV allo stesso tempo sportivo, compatto e dinamico.

Innanzitutto la Jeep Compass ha delle** dimensioni solide e ben proporzionate** sia esternamente, sia all’interno, dove presenta un abitacolo accogliente e spazioso, con sedili comodi e con un bagagliaio superiore alla media. Inoltre ne esistono ben **quattro allestimenti** che rispondono a tre diverse esigenze: la Sport, con la dotazione più completa con cerchi da 16’’ e i principali sistemi di sicurezza; la Longitude, con cerchi da 17”, dettagli cromati e sensori di parcheggio; la Limited, il vero top di gamma; la Business, ideale per le flotte aziendali.

Per quanto riguarda le tecnologie, **la Jeep Compass può vantare dei più avanzati e sofisticati sistemi di sicurezza** garantendo una guida tranquilla e piacevole: frenata d’emergenza, limitatore di velocità, mantenimento della corsia e un sistema di parcheggio automatico. Inoltre la Compass offre ben cinque proposte di guida: automatica, neve, sabbia, fango e roccia.

La Jeep Compass prevede **due tipologie di motori**: a benzina, con motore 1.4 turbo da 140 CV, con cambio manuale e 2 ruote motrici, e da 170 CV, con cambio automatico a 9 marce, trazione integrale, 2.4 da 184 CV, con cambio automatico, 4×4; diesel con motore 1.6 da 120 CV, con cambio manuale a sei marce e trazione anteriore, e 2.0 da 140 CV, con cambio manuale e automatico, 4×4, e da 170 CV, con cambio automatico, 4×4 Trailhawk.

Fonte | [VIA](https://www.clubalfa.it/28942-jeep-compass-candidata-al-premio-volante-doro-tra-le-suv-compatte.html)

Noleggia subito la tua [Jeep Compass!](https://www.nolosubito.it/veicoli/jeep/jeep-compass-limited-1-6-multijet-120cv/)',
  'Notizie',
  '',
  true,
  '2017-08-29T15:52:58.000Z'::timestamptz
)
