INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  '22° Edizione Automotive Dealer Day',
  'automotive-dealer-day',
  'Automotive Dealer Day La 22ª edizione dell''Automotive Dealer Day si è tenuta dal 14 al 16 maggio 2024 presso i padiglioni 11 e 12 di Veronafiere a Verona. Questo evento ha visto una partecipazione di oltre 6000 operatori del settore, sia italiani che internazionali, e più di 100 espositori. Il focus',
  'Automotive Dealer Day

La 22ª edizione dell''Automotive Dealer Day si è tenuta dal 14 al 16 maggio 2024 presso i padiglioni 11 e 12 di Veronafiere a Verona.
Questo evento ha visto una partecipazione di oltre 6000 operatori del settore, sia italiani che internazionali, e più di 100 espositori.

Il focus principale di quest''anno è stato sulla convergenza tra automotive e nuove forme di mobilità, esplorando dinamiche distributive innovative e le sfide future del settore. L''evento ha incluso workshop, dibattiti e analisi su tendenze emergenti, offrendo opportunità per aggiornarsi, condividere best practice e ascoltare storie di successo dai leader di mercato​.

Tra gli ospiti principali ci sono stati:

 	- **Marco Santucci** - CEO di Jaguar Land Rover Italia
 	- **Laura Babío Somoza** - Traffic Efficiency Cluster Lead di POLIS
 	- **Trevor Finn** - CEO di New World Automotive e Senior Strategic Advisor di Hedin Mobility Group AB
 	- **Ruymán Caballero** - Managing Director di Domingo Alonso Gran Canaria SLU
 	- **Eva Ziegler** - Docente alla Swiss Hotel Management School e Chief Marketing Officer
 	- **Gianluca De Ficchy** - CEO di Mobilize e Presidente del Consiglio di Amministrazione di RCI Banque SA
 	- **Andrea Crespi** - Presidente e CEO di Hyundai Italia
 	- **Giuseppe Stigliano** - Docente di Marketing e autore di "Redefining Retail"
 	- **Mathieu Nicaise** - Esperto di Mobilità

L''evento ha incluso anche numerosi workshop, dibattiti e analisi sulle tematiche, con un focus particolare sull''evoluzione della mobilità e l''integrazione dell''intelligenza artificiale. Qui il sito/profilo instagram ufficiale  [https://www.instagram.com/dealerday/](https://www.instagram.com/dealerday/)

22° Edizione Automotive Dealer Day',
  'Notizie',
  '',
  true,
