INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Autovelox 2024: Nuove Regole per la Sicurezza',
  'autovelox-2024-nuove-regole-per-la-sicurezza',
  'Ci saranno 12 mesi di tempo per l’adeguamento normativo - Per gli autovelox già installati alla data del 28 maggio e non conformi ai presupposti e alle prescrizioni del decreto, ci saranno dodici mesi di tempo per l’adeguamento alle disposizioni normative. Decorso il termine, saranno disinstallati s',
  'Autovelox 2024: Nuove Regole per la Sicurezza

A partire da maggio 2024, sono state introdotte nuove regole per l''uso degli autovelox in Italia. Queste modifiche mirano a rendere l''utilizzo dei dispositivi più trasparente e meno punitivo nei confronti degli automobilisti.
Il **28 maggio 2024** è stato pubblicato sulla [Gazzetta Ufficiale](https://www.gazzettaufficiale.it/) e quindi diventato effettivo, e voluto dal ministro Matteo Salvini con l’obiettivo di farli usare “soltanto **dove **effettivamente **servono**” .

Ecco le principali novità:

 	- **Divieto di utilizzo su strade con limiti di velocità inferiori a 50 km/h**: Gli autovelox fissi non possono essere collocati su strade urbane con limiti di velocità inferiori a 50 km/h. In questi casi, le infrazioni devono essere contestate immediatamente da pattuglie mobili​.
 	- **Regole per le strade extraurbane**: Gli autovelox possono essere utilizzati su strade extraurbane solo se il limite di velocità non è ridotto di oltre 20 km/h rispetto al limite massimo consentito. Ad esempio, su una strada con limite di 110 km/h, gli autovelox possono essere usati solo se il limite è di almeno 90 km/h​.
 	- **Posizionamento visibile e segnalato**: Gli autovelox devono essere chiaramente segnalati almeno un chilometro prima del punto di rilevamento, fuori dai centri abitati, e devono essere ben visibili.
 	- **Gestione centralizzata dei dispositivi**: La collocazione degli autovelox non sarà più decisa dai Comuni ma dai prefetti, che stabiliranno i tratti di strada dove è difficile o impossibile effettuare contestazioni immediate a causa delle condizioni strutturali. Questo dovrebbe garantire un uso più corretto e finalizzato alla sicurezza stradale.
 	- **Omologazione dei dispositivi**: Nonostante le nuove regole, resta aperta la questione dell''omologazione degli autovelox. Una recente sentenza della Cassazione ha stabilito che i dispositivi non omologati ma solo approvati non possono essere usati per emettere multe. Questo potrebbe portare a numerosi ricorsi finché la questione non sarà risolta definitivamente​.
 	- **Contestazione immediata**: È consentita l''uso di autovelox su veicoli in movimento per la contestazione immediata solo dove non è possibile installare postazioni fisse o mobili. Anche in questo caso, i dispositivi devono essere chiaramente riconoscibili.

Ci saranno 12 mesi di tempo per l’adeguamento normativo - Per gli autovelox già installati alla data del 28 maggio e non conformi ai presupposti e alle prescrizioni del decreto, ci saranno dodici mesi di tempo per l’adeguamento alle disposizioni normative. Decorso il termine, saranno disinstallati sino all’adeguamento alle disposizioni del decreto.

I dispositivi attualmente installati hanno 12 mesi di tempo per essere messi in regola: in caso contrario, saranno disinstallati fino al loro adeguamento. Ma attenzione: le **multe **che rileveranno saranno comunque valide in questo lasso di tempo.

E voi cosa ne pensate??? Scriveteci nei commenti la vostra opinione!
Autovelox 2024: Nuove Regole per la Sicurezza',
  'Notizie',
  '',
  true,
  '2024-05-31T12:58:50.000Z'::timestamptz
)
