INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Ford Capri: Rinasce nel 2024 come Crossover Elettrico',
  'ford-capri-rinasce-nel-2024-come-crossover-elettrico',
  'La Ford Capri sta per tornare , ma in una veste completamente nuova. La leggendaria coupé degli anni ''70 (in allegato) sarà reinventata come crossover elettrico, unendo il fascino retrò con la tecnologia moderna. Il nuovo modello utilizzerà la piattaforma MEB del Gruppo Volkswagen, già impiegata per',
  'La ***Ford Capri sta per tornare***, ma in una veste completamente nuova. La leggendaria coupé degli anni ''70 (in allegato) sarà reinventata come crossover elettrico, unendo il fascino retrò con la tecnologia moderna.

![image](https://www.nolosubito.it/wp-content/uploads/2024/06/ford-capri-1-serie_02-300x139.jpeg)

Il nuovo modello utilizzerà la piattaforma MEB del Gruppo Volkswagen, già impiegata per altri veicoli elettrici di Ford come l''Explorer EV.

Questa nuova Capri avrà dimensioni e caratteristiche simili a quelle della Volkswagen ID.5 e della Volvo C40, con un''autonomia prevista tra 400 e 500 km e una potenza di oltre 300 CV.
La Capri elettrica manterrà alcuni elementi di design caratteristici della versione originale, ma con un tocco contemporaneo adatto ai gusti moderni e alle esigenze ecologiche attuali​ ([MotorBox](https://www.motorbox.com/auto/magazine/auto-novita/ford-capri-nel-2024-ritornera-in-versione-elettrica))​.

L''uscita del nuovo modello è prevista per il 2024,** **sarà prodotta sulla stessa linea della Explorer nello stabilimento tedesco di Colonia.
*OLTRE 600 KM CON UNA RICARICA, p*er la nuova **Ford Capri **elettrica possiamo aspettarci caratteristiche tecniche molto simili a quelle della Explorer.
Nella configurazione che va più lontano, quella con la batteria da 78 kWh e la trazione posteriore, la Explorer dichiara un’autonomia di 602 km, che potrebbe essere leggermente migliorata grazie alle forme più aerodinamiche della Capri. I prezzi della suv-coupé saranno probabilmente in linea con quelli della Explorer, con un leggero sovrapprezzo.

**Voi cosa ne pensate della nuova proposta?**',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/06/ford-capri-1-serie_02-300x139.jpeg',
  true,
  '2024-06-10T10:56:27.000Z'::timestamptz
)
