INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Rimac e il suo futuro RoboTaxi',
  'rimac-e-il-suo-futuro-robotaxi',
  'Rimac RoboTaxi Rimac Automobili è un'' azienda Croata nota per la produzione di hypercar elettriche ad alte prestazioni, ha annunciato il lancio del suo primo prototipo di RoboTaxi, chiamato Rimac Urban Mobility Concept. Questo robotaxi rappresenta un importante passo avanti nella mobilità urbana sos',
  'Rimac RoboTaxi

Rimac Automobili è un'' azienda Croata nota per la produzione di hypercar elettriche ad alte prestazioni, ha annunciato il lancio del suo primo prototipo di RoboTaxi, chiamato Rimac Urban Mobility Concept. Questo robotaxi rappresenta un importante passo avanti nella mobilità urbana sostenibile e nell''automazione dei veicoli, che dovrebbe debuttare già nel *2026* a* Zagabria.*

![image](https://www.nolosubito.it/wp-content/uploads/2024/06/BB1oXh9M.jpeg)![image](https://www.nolosubito.it/wp-content/uploads/2024/06/BB1oXh9M-300x200.jpeg)

Quello dei robotaxi è un mercato in rapida espansione, la Tesla ha annunciato che presenterà il suo RoboTaxi il prossimo 8 agosto.
Il servizio è un progetto che ha preso vita nel 2017, quando la Rimac ha cominciato a lavorare alla sua tecnologia di guida autonoma. Nel 2021 ha ricevuto 200 milioni di euro dall’Unione Europea nell’ambito del piano di recupero da 6,3 miliardi per la Croazia, oltre che finanziamenti dal Gruppo Hyundai, impegnato nello sviluppo di un proprio robotaxi.
### Caratteristiche principali del Rimac Robotaxi

 	- **Design Avanzato**: Il design del robotaxi è futuristico e minimalista, progettato per offrire massima efficienza aerodinamica e un comfort superiore ai passeggeri.
 	- **Autonomia Elettrica**: Equipaggiato con una batteria di alta capacità, il robotaxi offre un''ampia autonomia, rendendolo ideale per l''uso continuo nelle città.
 	- **Guida Autonoma**: Integrato con la tecnologia di guida autonoma di livello 5, il robotaxi è in grado di operare senza intervento umano, utilizzando una combinazione di sensori, radar e intelligenza artificiale per navigare nel traffico urbano.
 	- **Sostenibilità**: Essendo un veicolo completamente elettrico, il robotaxi di Rimac contribuisce alla riduzione delle emissioni di CO2, favorendo un ambiente urbano più pulito e sostenibile.
 	- **Connettività**: Dotato di avanzati sistemi di connettività, il robotaxi offre un''esperienza utente interattiva e personalizzata, con la possibilità di connettersi a servizi digitali e di infotainment.

### Impatto sulla Mobilità Urbana

Il Rimac Robotaxi rappresenta una rivoluzione nel settore della mobilità urbana. Con l''integrazione della tecnologia di guida autonoma e la propulsione elettrica, questo veicolo offre una soluzione di trasporto efficiente, sicura e sostenibile. I robotaxi potrebbero ridurre significativamente la congestione del traffico e migliorare la qualità dell''aria nelle città, offrendo al contempo un''opzione di trasporto conveniente e accessibile per i cittadini.

L''annuncio del robotaxi di Rimac sottolinea l''impegno dell''azienda verso l''innovazione e la sostenibilità, dimostrando come le tecnologie avanzate possono essere applicate per affrontare le sfide della mobilità urbana contemporanea.

![image](https://www.nolosubito.it/wp-content/uploads/2024/06/RIMAC-VERNE-ROBOTAXI-300x167.jpeg) ![image](https://www.nolosubito.it/wp-content/uploads/2024/06/VERNE-Interior1-300x169.jpeg)

Chiamati tramite app, come un normale servizio di taxi, i veicoli della Verne stazioneranno in quelle che la Rimac chiama “motherships”, ossia "navi madre", depositi cittadini dove vengono caricati e puliti. I primi robotaxi saranno impiegati in via sperimentale nella capitale croata, ma la Rimac ha già confermato di aver stretto accordi con altre municipalità in Europa (tra cui Germania e Regno Unito) e in Medio Oriente. “Sul lungo termine Verne dovrebbe aiutare a eliminare la necessità di una seconda o terza auto di famiglia che occupa spazio, viene usata di rado e ha costi significativi, conclude la casa.

Voi cosa ne pensate???',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/06/BB1oXh9M.jpeg',
  true,
  '2024-06-27T08:47:21.000Z'::timestamptz
)
