INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'I nuovo ADAS: cosa è cambiato e tutti i sistemi alla guida',
  'i-nuovo-adas-cosa-e-cambiato',
  'I nuovo ADAS: cosa è cambiato. Che il sistema ADAS esistessero già questo lo sapevamo ma, dal 7 Luglio su tutte le auto di nuova immatricolazione Italiana, sono diventate obbligatori. Gli ADAS, ( Advanced Driver Assistance System) , rappresentano una serie di sistemi tecnologici progettati per suppo',
  'I nuovo ADAS: cosa è cambiato.

Che il sistema ADAS esistessero già questo lo sapevamo ma, dal 7 Luglio su tutte le auto di nuova immatricolazione Italiana, sono diventate obbligatori.

Gli ADAS, ( *Advanced Driver Assistance System)*, rappresentano una serie di sistemi tecnologici progettati per supportare e migliorare l''esperienza di guida aumentando la sicurezza. Questi sistemi utilizzano una combinazione di sensori, telecamere, radar e altre tecnologie per monitorare l''ambiente circostante il veicolo, fornendo assistenza attraverso vari meccanismi.
Lo stabilisce il Regolamento UE 2019/2144  e, secondo Unione Europea, migliora la sicurezza stradale diminuendo gli incidenti.

**Ma qual è la funzione reale degli ADAS? Scopriamolo insieme!**

Gli ADAS è un adattamento intelligente dell ***velocità***, la ***frenata*** automatica di emergenza, ***distanza di sicurezza***, ***mantenimento della corsia***,  il rilevamento degli ***ostacoli in retromarci*a, **riconoscimento dei ***segnali stradali, assistenza al parcheggio***

 	- **Mantiene i limiti di velocità (ISA): **Grazie alla lettura della segnaletica, è capace di mantenere i limiti di velocità.
 	- **Frenata automatica d''emergenza (AEB)**: Rileva ostacoli o veicoli davanti al veicolo e applica automaticamente i freni per prevenire o mitigare collisioni.
 	- **Cruise control adattivo (ACC)**: Mantiene una distanza di sicurezza costante dal veicolo che precede, regolando automaticamente la velocità del veicolo.
 	- **Mantenimento della corsia (LKA)**: Aiuta a mantenere il veicolo all''interno della corsia, intervenendo con leggere correzioni dello sterzo se il veicolo si avvicina ai bordi della corsia senza segnalazione.
 	- **Rilevamento degli angoli ciechi (BSD)**: Avvisa il conducente della presenza di veicoli negli angoli ciechi, rendendo più sicuri i cambi di corsia.
 	- **Riconoscimento dei segnali stradali (TSR)**: Identifica e mostra i segnali stradali, come limiti di velocità e segnali di stop, sul display del veicolo.
 	- **Assistenza al parcheggio**: Utilizza sensori e telecamere per aiutare il conducente nelle manovre di parcheggio, offrendo supporto visivo e acustico.

![image](https://www.nolosubito.it/wp-content/uploads/2024/07/bosch-guida-autonoma1-1.jpeg)

ADAS sulla frenata come funziona? Gli occhi del sistema sono la telecamera frontale e i sensori radar, che monitorano costantemente tutto il percorsa e tutto ciò che lo circonda, appena rileva che la distanza dell''ostacolo sta diventando troppo breve inizia a segnalare con suoni sonori e se il guidatore non dovesse ancora capire del futuro problema, adas inizia a frenare in maniera autonoma rallentando o addirittura fermare del tutto l''auto.
ADAS si può disattivare? Volendo SI! ma non è consigliabile in alcuni casi, però , si può diminuire la soglia d''intervento solo degli avvisi.

Un altro fattore molto importante ma non è stato ancora messo in atto non sappiamo ancora quando sarà obbligatorio, ma speriamo a breve, è ***L'' ALCOLOCK ***IMPEDISCE  la messa in modo della vettura se rileva un eccessivo tasso alcolemico.
![image](https://www.nolosubito.it/wp-content/uploads/2024/07/Alcolock.jpeg)
All''interno della vettura ci sarà questo oggetto come si fa con l''Etilometro  dove il guidatore deve soffiare in una cannuccia ovviamente l''oggetto è collegato all''auto e non darà il consenso di avviamento se rileva che il tasso alcolemico del conducente supera il limite! Per permettere l''avviamento del motore o si rifà il test oppure si cambia conducente! Non appena avrà rilevato la messa sicurezza alla guida il motore partirà!
In questi caso non si potrà disattivare la procedura, si punta a renderlo obbligatori a chi è stato già segnalato per guida in stato di ebbrezza.',
  'Approfondimenti',
  'https://www.nolosubito.it/wp-content/uploads/2024/07/bosch-guida-autonoma1-1.jpeg',
  true,
  '2024-07-24T08:42:42.000Z'::timestamptz
)
