INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Da Settembre 2024 obbligatori i Seggiolini i-Size',
  'da-settembre-2024-obbligatori-i-seggiolini-i-size',
  'Dal 1° settembre 2024 , entrerà in vigore la nuova normativa europea ECE R129, conosciuta come i-Size , per i seggiolini auto per bambini. Questa normativa sostituirà completamente la precedente ECE R44/04 e comporterà diversi cambiamenti significativi progettati per migliorare la sicurezza dei bamb',
  'Dal **1° settembre 2024**, entrerà in vigore la nuova normativa europea ECE R129, conosciuta come **i-Size**, per i seggiolini auto per bambini. Questa normativa sostituirà completamente la precedente ECE R44/04 e comporterà diversi cambiamenti significativi progettati per migliorare la sicurezza dei bambini durante i viaggi in auto. Si troveranno nei negozi e online.
### Principali cambiamenti della normativa i-Size (ECE R129)

 	**Classificazione basata sull''altezza**:

 	I seggiolini saranno classificati in base all''altezza del bambino, non più al peso. Le due principali categorie saranno:

 	- i-Size fino a 100 cm (indicativamente per bambini sotto i 18 kg)
 	- i-Size da 100 a 150 cm (per bambini dai 15 ai 36 kg)​.

 	**Obbligo del sistema Isofix**:

 	- Diventerà obbligatorio utilizzare il sistema Isofix per i seggiolini destinati a bambini fino a 105 cm di altezza. Questo sistema fissa il seggiolino direttamente al telaio dell''auto, garantendo una maggiore stabilità e sicurezza rispetto all''ancoraggio con cinture di sicurezza tradizionali.

 	**Posizionamento contro il senso di marcia fino a 15 mesi**:

 	- I bambini dovranno viaggiare nel senso contrario di marcia fino a 15 mesi di età (circa 76 cm). Questo posizionamento è stato dimostrato più sicuro per proteggere meglio la testa e il collo in caso di incidente​.

 	**Protezioni laterali obbligatorie**:

 	- Tutti i seggiolini devono essere dotati di protezioni laterali omologate, che devono superare specifici crash test per impatti laterali, aggiungendo un ulteriore livello di sicurezza per i bambini​​.

### Cosa fare con i vecchi seggiolini?

I seggiolini omologati secondo la vecchia normativa ECE R44 potranno ancora essere utilizzati, anche se non saranno più prodotti né commercializzati. Tuttavia, per chi deve acquistare un nuovo seggiolino, è consigliabile optare per quelli conformi alla nuova normativa i-Size, poiché offrono un livello di sicurezza più elevato​.
### Consigli per l''uso sicuro dei seggiolini

 	- **Conservare il manuale d’istruzione**: utile per il corretto montaggio del seggiolino su diverse auto.
 	- **Legare sempre il bambino, anche per tragitti brevi**: il 40% degli incidenti mortali avviene su distanze inferiori ai 3 km.
 	- **Evitare seggiolini di seconda mano**: potrebbero avere danni non visibili.
 	- **Verificare l’integrità del seggiolino**: usura e danneggiamenti possono compromettere la sicurezza.
 	- **Sostituire il seggiolino dopo un incidente**: anche piccoli danni possono ridurre la protezione offerta​​.

In sintesi, la normativa i-Size mira a migliorare significativamente la sicurezza dei bambini in auto, introducendo standard più rigorosi basati su evidenze scientifiche e test di sicurezza avanzati.',
  'Approfondimenti',
  '',
  true,
  '2024-08-05T08:44:30.000Z'::timestamptz
)
