INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Mattoncini e Motori = Passione Lego',
  'mattoncini-e-motori-passione-lego',
  'Mattoncini e Motori = Passione Lego Quanti di voi sono amanti o sono affascinati dal mondo della Lego? La grande azienda ci stupisce ancora, vediamo nel dettaglio il perchè... La LEGO è un''azienda danese fondata nel 1932 da Ole Kirk Christiansen, che è diventata un''icona mondiale nel settore dei gio',
  'Mattoncini e Motori = Passione Lego

Quanti di voi sono amanti o sono affascinati dal mondo della Lego? La grande azienda ci stupisce ancora, vediamo nel dettaglio il perchè...

La LEGO è un''azienda danese fondata nel 1932 da Ole Kirk Christiansen, che è diventata un''icona mondiale nel settore dei giocattoli grazie ai suoi celebri mattoncini. Nel corso degli anni, LEGO ha sviluppato un''incredibile varietà di set che spaziano da temi come il fantasy e la fantascienza fino a quelli più realistici e moderni. Tra questi, una delle **collezioni più apprezzate** dagli appassionati di **motori** è quella dedicata alle auto di marca.
La serie dedicata alle auto di marca, conosciuta come **LEGO Speed Champions** e **LEGO Technic**, è diventata particolarmente popolare tra gli adulti e i collezionisti. Queste serie consentono di costruire modelli dettagliati e realistici di alcune delle auto più iconiche del mondo, dalle supercar ai veicoli da corsa.

Infatti da poco è stata messa in vendita la famosa Mercedes-Benz G 500.
![image](https://www.nolosubito.it/wp-content/uploads/2024/08/Schermata-2024-08-08-alle-09.29.09-1.png) Acquistabile sul sito ufficiale o negli store [https://www.lego.com/it-it](https://www.lego.com/it-it)

Qual è la differenza tra  **LEGO Speed Champions** e **LEGO Technic:**

**LEGO Speed Champions** è una linea che riproduce in scala ridotta le auto più famose del mondo. Con un''enfasi su dettagli accurati e adesivi che rappresentano fedelmente i loghi e i design delle vetture originali. Tra i modelli più noti ci sono:

 	- **Ferrari**: Con modelli come la Ferrari F8 Tributo e la Ferrari 488 GT3.
 	- **Porsche**: Modelli come la Porsche 911 Turbo e la Porsche 911 RSR sono tra i più apprezzati.
 	- **McLaren**: La McLaren Senna e la McLaren Elva sono alcuni esempi di supercar moderne che gli appassionati possono costruire, ognuna con dettagli che riflettono l''innovazione tecnologica del marchio.

**LEGO Technic**, invece, si rivolge a un pubblico più adulto e appassionato di ingegneria, con set più complessi che includono funzioni meccaniche realistiche come motori funzionanti, sospensioni indipendenti e sistemi di sterzo. Alcuni dei set più impressionanti includono:

 	- **Bugatti Chiron**: Un capolavoro di LEGO Technic, con oltre 3.600 pezzi, questo modello include un motore W16 con pistoni mobili, un cambio a 8 velocità funzionante e uno sterzo attivo.
 	- **Lamborghini Sián FKP 37**: Con 3.696 pezzi, questo set è un tributo alla tecnologia avanzata e al design futuristico della Lamborghini, completo di dettagli accurati e un colore verde lime distintivo.
 	- **Porsche 911 GT3 RS**: Con una livrea arancione brillante, questo set offre una costruzione dettagliata che include un motore piatto a 6 cilindri e un cambio sequenziale funzionante.

Nel corso degli anni oltre all''uscita della Mercedes-Benz G500 sono uscite tante altre vetture 4 e 2 ruote, sia di corsa che quelle di lussa.

 	Porsche 911;
 	Land Rover Classic Defender 90;
 	Mercedes-Benz G 500;
 	Yamaha MT-10 SP;
 	Porsche 963.

Molte altre collezioni sono uscite e l''azienda ha promesso che ne usciranno molte altre ancora!

Mattoncini e Motori = Passione Lego

