INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'In arrivo la nuova Smart #5',
  'in-arrivo-la-nuova-smart-5',
  'Nuova opportunità per la casa Smart, in arrivo la nuova Smart #5',
  '**Nuova opportunità per la casa Smart, in arrivo la nuova Smart #5**

Proprio ieri hanno presentato a Byron Bay in Australia la nuova ***Smart #5***,  un SUV elettrico grande 4.7 mt.

Vediamo un attimo la storia della Smart, nasce da Nicolas Hayek, l''imprenditore svizzero fondatore di Swatch, il famoso marchio di orologi. Negli anni ''80, Hayek ebbe l''intuizione di applicare la filosofia del suo marchio – ovvero un design accattivante, personalizzabile e accessibile – al settore automobilistico. Hayek si rese conto che per realizzare la sua visione aveva bisogno di un partner con esperienza nel settore automobilistico. Dopo aver esplorato diverse collaborazioni, si associò con Daimler-Benz (oggi Mercedes-Benz). Nel 1994, nacque una joint venture chiamata **Micro Compact Car AG** (MCC), con sede a Biel, in Svizzera.

Il primo modello, del 1998, fu la Smart City Coupè, dopo di che iniziano ad uscire vari modelli  molto simili tra loro come ad esempio la **Fortwo**  (3 porte - 2 posti) era una city car due posti, caratterizzata da dimensioni ultracompatte e un design innovativo.![image](https://www.nolosubito.it/wp-content/uploads/2024/08/smart-fortwo-primo-contatto_01.jpeg) e la **ForFour **( 5 porte - 4 posti )![image](https://www.nolosubito.it/wp-content/uploads/2024/08/1920_626334-1118859-2126-1684-23-foto-1-3.jpeg)

Il nome "Smart" deriva dall''unione delle parole "Swatch", "Mercedes", e "art", che simboleggiano la collaborazione tra Swatch e Mercedes-Benz e l''idea di creare un''auto d''arte, funzionale e di design.

Arriviamo nel 2022  e 2023 auto elettriche del tipo Crossover SUV la **Smart #1** e la  **Smart #3. **Dove cambia solo a livello estetico.
![image](https://www.nolosubito.it/wp-content/uploads/2024/08/hero-banner.avif) ![image](https://www.nolosubito.it/wp-content/uploads/2024/08/Schermata-2024-08-29-alle-10.24.31-e1724920463237.png)

Ieri, come detto precedentemente, è stato presentata la **Smart #5** sempre un SUV elettrico, rappresenta una svolta significativa rispetto ai modelli precedenti. Questo SUV compatto elettrico, progettato con un''estetica più sportiva e dinamica, è pensato per chi cerca un equilibrio tra efficienza, stile e innovazione.

![image](https://www.nolosubito.it/wp-content/uploads/2024/08/smart-progetto.png)

Esteticamente, la Smart #5 si distingue per linee fluide e moderne, con una griglia frontale più aggressiva e fari a LED sottili che conferiscono un look grintoso. La carrozzeria è più robusta rispetto ai modelli passati, ma mantiene dimensioni compatte ideali per la guida urbana.

![image](https://www.nolosubito.it/wp-content/uploads/2024/08/Schermata-2024-08-29-alle-09.19.40-e1724920942731.png)

L''interno è molto innovativo, con un design minimalista e un''interfaccia utente all''avanguardia. Il cruscotto digitale e lo schermo touchscreen centrale offrono tutte le informazioni e necessarie per una guida confortevole e connessa.
![image](https://www.nolosubito.it/wp-content/uploads/2024/08/Schermata-2024-08-29-alle-09.20.01.png)
I materiali utilizzati sono di alta qualità, con finiture eleganti che enfatizzano l''attenzione ai dettagli. La Smart #5 è alimentata da un motore elettrico che garantisce una guida silenziosa e a zero emissioni, rimanendo fedele alla tradizione del marchio di offrire soluzioni sostenibili per la mobilità urbana.

![image](https://www.nolosubito.it/wp-content/uploads/2024/08/smart-5-lato.webp) ![image](https://www.nolosubito.it/wp-content/uploads/2024/08/smart-5-versioni.webp)
La smart #5 è **disponibile in due allestimenti**: Summit Edition e Premium+. La Summit Edition include l''Adventurers Collection, un pacchetto che offre accessori per attività all''aperto, come un gancio di traino elettrico.

Una bella innovazione per la casa Smart, addirittura da posizionarsi come un concorrente diretto di SUV di alta gamma come la BMW X3. Inoltre è stato svelato e confermato che l''azienda sta sviluppando una nuova city car elettrica, ma per renderla sostenibile finanziariamente è necessario trovare un partner strategico, probabilmente la ForTwo?? Ancora non si sa con precisione ma sicuramente ci stanno lavorando.

Voi cosa ne pensato di tutto ciò? Parliamone insieme nei commenti.',
  'Approfondimenti',
  'https://www.nolosubito.it/wp-content/uploads/2024/08/smart-fortwo-primo-contatto_01.jpeg',
  true,
  '2024-08-29T08:30:08.000Z'::timestamptz
)
