INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'La Ford si ritira...',
  'la-ford-si-ritira',
  'Ford ci ripensa e fa un passo indietro',
  '**Ford ci ripensa e fa un passo indietro**

Ford ci ripensa e fa un passo indietro: Suv elettrico troppo costoso, punterà sulle piccole e ibride, vediamo meglio del perchè di questa decisione.
Ha deciso di cancellare il progetto di un SUV F-150 Lightning, a tre file di sedili, che era inizialmente previsto per il 2025 ma successivamente posticipato al 2027. Questo cambio di rotta riflette le sfide che l''industria automobilistica sta affrontando nel settore degli EV, le cause sono diversi fattori economi e di mercato.

Sono vari i problemi che hanno hanno spinto a questa decisione, ma vediamo quali:

 	- **Fornitura e costi: **Sicuramente, ma non solo per la Ford, tutto il mondo delle vetture stanno avendo problemi con le forniture e aumenti continui sulle materie prime e batterie
 	- **Problemi sulla qualità e sicurezza: **Durante la produzione, hanno riscontrato vari problemi non solo sulla qualità ma anche sulla sicurezza.
 	- **Scarsa richiesta negli Usa:** C''è da dire anche che negli Stati Uniti c''è una scarsa domanda di auto elettriche.
 	- **Competizione e pressione: **Come abbiamo detto poc''anzi, il mondo delle vetture elettriche è in continua evoluzione è quindi altamente competitivo, cosi da far prendere la decisione di ritirarla temporaneamente per rivedere la propria offerta e assicurarsi di avere un prodotto competitivo quando riprenderanno la produzione.
 	- **Strategia di mercato:** Ford potrebbe anche stare riconsiderando la sua strategia di mercato per i veicoli elettrici. Potrebbero essere in fase di pianificazione di una nuova generazione.

Certo che questo "passo indietro" costerà all''azienda una cifra stimata in 1,9 miliardi di dollari. Infatti non crediamo che la Ford abbia detto del tutto addio all'' elettrico ma un arrivederci, concentrandosi attualmente sull''ibrido includendo i modelli Explorer ed Expedition.

Fatto sta che il vero motivo della decisione presa non la sapremo mai, sono tutte opposizioni e dati verificati negli Usa.

Voi cosa ne pensate??

* *',
  'Approfondimenti',
  '',
  true,
  '2024-08-28T09:15:21.000Z'::timestamptz
)
