INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'E io pago...!',
  'e-io-pago-bollo-auto',
  '" E IO PAGO! " by Totò Bollo auto Avete presente la scena di Totò, nel film 47 morto che parla quando ripete svariate volte "E io pago?" ebbene è successo ad un cittadino del Lazio che, dopo un anno dalla denuncia dell''auto rubata, gli viene richiesto di pagare il bollo auto. Nel Novembre del 2020, ',
  '#### **" E IO PAGO! " by Totò**

Bollo auto
Avete presente la scena di Totò, nel film  *47 morto che parla *quando ripete svariate volte  ***"E io pago?"**** *ebbene è successo ad un cittadino del Lazio che, dopo un anno dalla denuncia dell''auto rubata, gli viene richiesto di pagare il bollo auto.

Nel Novembre del 2020, racconta il cittadino, si accorge che la sua auto la Toyota C-HR era scomparsa, quindi ne aveva subito il furto. Stesso quella giornata si reca presso il commissariato di polizia di Ostia per denunciare l''accaduto e iniziare le pratiche per il risarcimento della sua assicurazione.
Una volta aver ricevuto l''importo pattuito, il caso era stato chiuso definitivamente. Quando dopo quasi 4 anni riceve una cartella dall''Agenzia delle entrate, dove la Regione Lazio gli chiedeva il pagamento del bollo 2021 per quell''auto rubata. La prima cosa, giustamente, che pensò il cittadino è che c''era stato un errore. Inizia le pratiche dell''annullamento allegando anche la denuncia fatta nel 2020. Dopo svariati mesi riceve, finalmente, una risposta tramite PEC dalla Regione Lazio che, essendo lui rientrato in possesso della vettura nel 2021, era tenuto a pagare il bollo, ma il cittadino non aveva mai più rivisto la sua auto da quel Novembre 2020.

Quindi cosa è successo realmente?  La pratica della denuncia effettivamente era andata in porto e portata a buon fine, ma chiedendo un estratto cronologico chiesto al PRA risulta che effettivamente l''interruzione del bollo c''era però nel giugno 2021 il cittadino Laziale era rientrato in possesso del veicolo dal punto di vista amministrativo, questo perchè un autodemolitore Milanese ne denuncia il ritrovamento della vettura Toyota. Però il proprietario non era stato mai messo a conoscenza del ritrovamento ne dalla polizia e ne dall''assicurazione, e quindi si era rigenerato il bollo siccome risultata che la vettura era stata riconsegnata al proprietario.

L''auto era stata rubata e dopo 1 anno è stato ritrovata a Milano. Il Milanese ne denuncia il ritrovamento ma il Laziale non era mai stato avvisato di questo ritrovamento. Quindi, dopo quasi 4 anni, il Laziale ha ritrovato l''auto rubata e sicuramente avrà richiesto risarcimento dall''assicurazione che non era stato avvisato dell''accaduto.

Invece a voi è mai capitato qualcosa di assurdo o simile ??',
  'Approfondimenti',
  '',
  true,
  '2024-08-30T10:03:47.000Z'::timestamptz
)
