INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Fabrizio Longo: Direttore Audi morto per colpa della sua grande passione',
  'morto-fabrizio-longo',
  'Fabrizio Longo: Direttore Audi morto per colpa della sua passione Mondo dell''automotive in lutto, per Fabrizio Longo, direttore dell''Audi Italia. Vittima dell''incidente, direttore di Audi Italia, in montagna avvenuto intorno alle 13 di sabato 31 agosto in prossimità di cima Payer, nel gruppo dell''Ad',
  '#### Fabrizio Longo: Direttore Audi morto per colpa della sua passione

Mondo dell''automotive in lutto, per Fabrizio Longo, direttore dell''Audi Italia.
Vittima dell''incidente, direttore di Audi Italia, in montagna avvenuto intorno alle 13 di sabato 31 agosto in prossimità di cima Payer, nel gruppo dell''Adamello, in Trentino. L''uomo stava percorrendo da solo la via ferrata che porta fino alla vetta quando, a circa 3.000 metri di altezza, è caduto nel vuoto per circa 200 metri. Per lui non c''è stato nulla da fare.

**Chi era Fabrizio Longo**

Era un manager italiano noto per il suo ruolo nell''industria automobilistica. È stato Direttore del marchio Audi in Italia, dove ha guidato le operazioni del brand all''interno del mercato italiano. Durante la sua carriera, Longo ha svolto un ruolo chiave nello sviluppo e nell''espansione della presenza di Audi nel paese, contribuendo a consolidare la reputazione del marchio come uno dei leader nel settore delle auto di lusso.

Oltre al suo lavoro con Audi, Longo ha accumulato una vasta esperienza nel settore automobilistico, avendo ricoperto ruoli di rilievo anche per altre case automobilistiche, come Fiat e Nissan. Il suo approccio alla gestione e alla leadership è stato caratterizzato da una forte attenzione all''innovazione e alla sostenibilità, elementi che ha cercato di integrare nelle strategie aziendali.

Fabrizio Longo era riconosciuto come una figura influente nell''industria automobilistica italiana, grazie alla sua capacità di combinare visione strategica e competenze operative per guidare la crescita e il successo delle aziende con cui ha lavorato.

## "Era un alpinista esperto e attento"

La Federazione italiana sport invernali (Fisi) sottolinea in una nota che "il manager, grande appassionato di montagna e alpinista molto esperto e attento, nella mattinata del 31 agosto aveva intrapreso il percorso in solitaria, ma a un certo punto, forse dopo aver perso l’equilibrio, è precipitato nel vuoto per 200 metri".

Come ricorda la stessa Federazione, Fabrizio Longo era nato a Rimini nel 1962. Aveva una grande passione per le montagne, e, sotto la sua guida, Audi Italia ha legato la sua immagine a quella della Federazione Italiana Sport Invernali. "Un lutto terribile per federazione - ha detto il presidente della Fisi Flavio Roda - che con Longo ha collaborato proficuamente per anni. Ci stringiamo alla famiglia in questo momento di grande dolore e allo staff di Audi Italia".',
  'Notizie',
  '',
  true,
  '2024-09-03T07:25:36.000Z'::timestamptz
)
