INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Xiaomi oltre ai cellulari ora anche le automobili',
  'xiaomi-automobili',
  'Xiaomi oltre ai cellulari ora anche le automobili',
  'Xiaomi oltre ai cellulari ora anche le automobili

L''Azienda cinese Xiaomi non si ferma alla produzione di Smartphone ma inizia anche a progettare autovetture elettriche!
Il gigante dell''elettronica di consumo Xiaomi inizia con SU7, la berlina due volumi che sarà commercializzata quest''anno. Venne presentata già a dicembre 2023 ma lanciata formalmente a marzo 2024 a Pechino,  iniziando a prendere ordini per l''auto già in quel giorno.

![image](https://www.nolosubito.it/wp-content/uploads/2024/09/Xiaomi-SU7-il-primo-veicolo-elettrico-dellazienda-cinese.webp)
Xiaomi SU7 è una berlina-coupé a quattro porte lunga 4.99 mm, larga 1.96, alta 1.45 mm e con un passo di tre metri esatti. È elettrica ed è proposta con tre tagli batteria. A seconda della versione ha un motore posteriore da 299 CV o due unità propulsive. Mentre la velocità massima è di 210 km/h.

![image](https://www.nolosubito.it/wp-content/uploads/2024/09/Xiaomi-su7-interni-0.webp)

Se e quando la SU7 arriverà in Europa, non aspettatevi di pagarla 27.900 euro come in Cina. Ha annunciato che non ci sono piani a breve termine per la vendita della SU7 in Europa e in altri mercati.

Xiaomi, nota azienda cinese conosciuta principalmente per smartphone ed elettronica di consumo, ha recentemente espanso i propri orizzonti anche nel settore automobilistico. L''azienda ha annunciato piani ambiziosi per entrare nel mercato delle auto elettriche (EV), con l''obiettivo di diventare un attore di rilievo in questo settore.

Nel 2021, Xiaomi ha ufficialmente rivelato il suo investimento di 10 miliardi di dollari in un progetto dedicato allo sviluppo di veicoli elettrici nei prossimi 10 anni. La nuova divisione automobilistica di Xiaomi mira a progettare, produrre e vendere automobili elettriche intelligenti.

Questo ingresso nel settore EV si inserisce in una più ampia strategia di Xiaomi per diversificare il suo portafoglio di prodotti, includendo tecnologie smart home, dispositivi IoT, e ora automobili elettriche, sfruttando la propria esperienza in AI e software per integrare funzionalità avanzate nei veicoli.

Al momento, Xiaomi ha già registrato diverse aziende legate alla mobilità elettrica e ha collaborato con produttori del settore per avviare la fase di sviluppo e produzione. L''azienda punta a lanciare i primi modelli sul mercato entro il 2024 o 2025.

Sebbene Xiaomi sia relativamente nuova nel settore automobilistico, la sua capacità di innovare in ambito tecnologico e il vasto seguito di clienti globali potrebbero dare all''azienda un vantaggio competitivo nel mercato delle auto elettriche.',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/09/Xiaomi-SU7-il-primo-veicolo-elettrico-dellazienda-cinese.webp',
  true,
  '2024-09-04T12:59:48.000Z'::timestamptz
)
