INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Hacker Auto, cosa sta succedendo?',
  'hacker-auto',
  'Hacker Auto, cosa sta succedendo? Come vi abbiamo anticipato ultimamente sta succedendo un episodio molto strano e il rischio sta diventando molto evidente negli ultimi anni. Come già sappiamo il mondo automotive si è evoluto e ha sviluppato sistemi innovativi che hanno dato il via ad auto sempre pi',
  'Hacker Auto, cosa sta succedendo? Come vi abbiamo anticipato ultimamente sta succedendo un episodio molto strano e il rischio sta diventando molto evidente negli ultimi anni.

Come già sappiamo il mondo automotive si è evoluto e ha sviluppato sistemi innovativi che hanno dato il via ad auto sempre più connesse.

I vantaggi delle multifunzioni date dalla connessione a sistemi informatici si scontra però con il rischio sempre più reale di hackeraggio.

Come dimostrato dal Global Automotive Cybersecurity Report, si tratta di episodi sempre più frequenti in tutto il mondo che hanno dato inizio a preoccupazioni tra automobilisti e Case costruttrici.

Uno degli esempio di car hacking è sulla **Jeep Cherokee (2015)**: Un l''attacco remoto da parte di due ricercatori di sicurezza informatica. Hanno dimostrato come, sfruttando una vulnerabilità nel sistema di infotainment, potevano prendere il controllo del veicolo, compreso il sistema di sterzo e i freni, a distanza.

E anche** Tesla Model S**: In vari test, sono state scoperte vulnerabilità nei sistemi della Tesla che permettevano agli hacker di controllare funzionalità. Tesla, tuttavia, ha dimostrato un forte impegno nel risolvere velocemente queste falle con aggiornamenti over-the-air.

Come possiamo proteggerci? Purtroppo al momento non ci sono modi valide ma ci sono consigli da prendere assolutamente in considerazione:

 	- **Aggiornamenti del software**: È essenziale mantenere aggiornati i sistemi informatici dell''auto, come si farebbe per uno smartphone o un computer. Molte case automobilistiche offrono aggiornamenti periodici per correggere vulnerabilità.
 	- **Attenzione alle chiavi elettroniche**: Utilizzare borse schermate per bloccare i segnali delle chiavi elettroniche può prevenire il furto tramite "relay attack", un metodo in cui gli hacker estendono il segnale della chiave per aprire e avviare l''auto a distanza.
 	- **Disabilitare funzionalità non utilizzate**: Se non si utilizza il Wi-Fi o il Bluetooth del veicolo, potrebbe essere saggio disabilitarli per ridurre il rischio.
 	- **Monitoraggio della sicurezza**: Alcune aziende offrono soluzioni di monitoraggio della sicurezza, simili agli antivirus per computer, che possono aiutare a rilevare anomalie o tentativi di attacco.

Gli aggiornamenti infatti forniscono delle nuove versioni al software di infotainment che permettono di sbarrare l’accesso ai canali di entrata degli hacker.

 

Al momento nell''anno 2019 l’Unione Europea ha stanziato 450 milioni di euro per finanziare lo sviluppo e l’introduzione di dispositivi tecnologici rivolti alla sicurezza informatica.',
  'Approfondimenti',
  '',
  true,
  '2024-09-11T10:20:53.000Z'::timestamptz
)
