INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Lutto nel mondo del motociclistico - Luca Salvadori',
  'luca-salvadori-lutto',
  'Una tragica notizia rompe la quiete nel mondo del motociclistico, ma non solo. Il 14 Settembre 2024 Luca Salvadori, è morto. Pilota che ha corso nel CIV, in MotoE e che era impegnato in una gara dell’Europeo road race sul circuito stradale di Frohburg, lì ha avuto un incidente in qualifica, ma non c',
  'Una tragica notizia rompe la quiete nel mondo del motociclistico, ma non solo.
Il 14 Settembre 2024 Luca Salvadori, è morto. Pilota che ha corso nel CIV, in MotoE e che era impegnato in una gara dell’Europeo road race sul circuito stradale di Frohburg, lì ha avuto un incidente in qualifica, ma non ce l’ha fatta nonostante gli immediati soccorsi e il ricovero in ospedale. Nella qualifica di quella sera, il tedesco Didier Grams è caduto nella curva veloce di fronte al paddock e anche Luca Salvadori è rimasto coinvolto nell’incidente. Inutili i soccorsi, è morto in ospedale per le ferite riportate.

Il motociclismo è uno sport che regala emozioni, adrenalina e voglia di vivere, ma a volte offre il suo lato oscuro e presenta il conto.

Salvadori, classe 1992, era un volto noto ai giovani e agli appassionati di motociclismo, che seguivano con piacere i video che realizzava per il suo canale YouTube. Accanto alla vita da pilota, Luca aveva intrapreso la strada del videomaker, creando video in cui raccontava storie, commentava le gare del mondiale e trasmetteva la sua esperienza in pista attraverso i video che realizzava e montava.

Sulla tuta aveva scritto «Like a Sir», «Come un signore»: Luca Salvadori voleva correre cavandosela da solo, senza gli aiuti del padre importante produttore musicale e fondatore del team Trident, così era diventato anche influencer. Si era messo in testa di gareggiare all''isola di Man e si voleva allenare nelle gare su strada. I ricordi di Jovanotti e Guido Meda.

Qui il suo [profilo](https://www.instagram.com/lucasalvadoriofficial/) instagram - Con dispiace e tristezza.',
  'Notizie',
  '',
  true,
  '2024-09-16T08:32:16.000Z'::timestamptz
)
