INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Nuova Cupra TerraMar',
  'nuova-cupra-terramar',
  'Cupra TerraMar Nel corso dei prossimi mesi la gamma CUPRA si amplierà accogliendo un nuovo modello che costituirà la sua punta di diamante: la Terramar. Un SUV di dimensioni generose che si unirà alla lineup CUPRA. Il marchio sportivo ha già offerto una visione preliminare della Terramar nel corso d',
  'Cupra TerraMar

Nel corso dei prossimi mesi la gamma CUPRA si amplierà accogliendo un nuovo modello che costituirà la sua punta di diamante: la Terramar. Un SUV di dimensioni generose che si unirà alla lineup CUPRA.

Il marchio sportivo ha già offerto una visione preliminare della Terramar nel corso di alcuni eventi ufficiali, senza fornire dettagli approfonditi.

La CUPRA ha annunciato che questo SUV segnerà una tappa importante nel loro piano di elettrificazione, e il modello sarà disponibile sia in versione a combustione che ibrida plug-in. Le tempistiche possono variare a seconda della produzione e delle strategie di mercato di CUPRA. L''uscita dovrebbe essere a fine anno 2025.

Con i suoi 4,52 mt di lunghezza, Terramar si colloca nel cuore del segmento SUV di classe A, dove il potenziale di mercato è più elevato.
L''equilibrio tra le dimensioni complessive e la lunghezza del passo conferisce al veicolo una silhouette sportiva e atletica, mentre all''interno si traduce in un''ottimale distribuzione dello spazio e abitabilità. La gamma powertrain è vasta e diversificata, pensata per soddisfare ogni esigenza del mercato. L''offerta comprende motori a combustione interna, tra cui i propulsori turbocompressi 2.0 TSI, tutti associati al cambio DSG a doppia frizione a 7 rapporti e alla trazione integrale 4DRIVE, con potenze di 204 CV e 265 CV. Per quanto riguarda le opzioni elettrificate, il 1.5 Hybrid con tecnologia mHEV eroga 150 CV, supportato da una batteria agli ioni di litio. La tecnologia Plug-in Hybrid di nuova generazione sarà disponibile con motori 1.5 Hybrid nelle versioni da 204 CV e 272 CV.

![image](https://www.nolosubito.it/wp-content/uploads/2024/09/new-cupra-terramar-2024-rear-view.png)

CUPRA Terramar sarà disponibile anche nella versione VZ che garantisce un upgrade ai contenuti stilistici, tecnici e tecnologici più esclusivi, oltre all''accesso ai propulsori a più alte perfomance.

![image](https://www.nolosubito.it/wp-content/uploads/2024/09/11b65e9351c0c5ca9595f1410694a88d.jpeg)

![image](https://www.nolosubito.it/wp-content/uploads/2024/09/3dddc1bfad447da70c3b730816058ef8.jpeg)',
  'Approfondimenti',
  'https://www.nolosubito.it/wp-content/uploads/2024/09/new-cupra-terramar-2024-rear-view.png',
  true,
  '2024-09-18T08:20:42.000Z'::timestamptz
)
