INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Totem Automobili - Riccardo Quaggio',
  'totem-automobili-alfa-romeo',
  'Alfa Romeo e il suo ex designer. Sapete chi è Riccardo Quaggio ? Un veneto ex Design di Alfa Romeo . Solo un pazzo potrebbe lasciare un lavoro fisso presso la casa automobilistica, e quel pazzo è proprio Riccardo Quaggio. Un giorno decide di lasciare Alfa Romeo per seguire la sua passione ovvero que',
  'Alfa Romeo e il suo ex designer.
Sapete chi è **Riccardo Quaggio**? Un veneto ex *Design di Alfa Romeo*.
Solo un pazzo potrebbe lasciare un lavoro fisso presso la casa automobilistica, e quel pazzo è proprio Riccardo Quaggio. Un giorno decide di lasciare Alfa Romeo per seguire la sua passione ovvero quello di diventare costruttore di auto, in particolare della Giulia Coupè degli anni 60 fondando anche una casa produttrice di coupè Ares in versione elettrica (GT electric) o un V6 Biturbobenzina (Gt Super) chiamata Totem Automobibli

Innamorato della Giulia GTAm degli anni 60, è tornato in Veneto, si è comprato una Giulia GT e l''ha smontata pezzo pezzo in un vecchio capannone del nonno. Ha venduto tutti i pezzi che non gli servivano, ha cercato vari attrezzi che gli servivano  e ha iniziato a costruire la sua prima auto. Tutto ciò è accaduto nel 2020 quando viene presentato il prototipo della Totem GT.

Una bellissima invenzione per il made in italy tutti giovani guidati da un''unica passione,  che si occupano di *restomod*, ovvero la modernizzazione di automobili classiche, in particolare modelli di Alfa Romeo. Insomma Quaggio ha deciso di intraprendere la propria strada, insoddisfatto dalla direzione che l''azienda stava prendendo. Ha quindi fondato Totem Automobili con l''obiettivo di rendere omaggio alla tradizione dell''Alfa Romeo, combinando design classico con tecnologia moderna.

Uno dei progetti principali di Totem è la rivisitazione dell''Alfa Romeo Giulia GTA degli anni ''60. L''azienda produce due versioni: una con un motore a combustione interna da 600 cavalli e un''altra con una propulsione elettrica da 500 cavalli. Le auto sono realizzate con un telaio in fibra di carbonio e mantengono solo il 10% del telaio originale, offrendo prestazioni e design di altissimo livello.

Coraggio da vendere insomma, perchè non tutti avrebbero avuto questo coraggio di Riccardo Quaggio, e voi cosa ne pensate? a voi i commenti...

[rl_gallery id="2061567"]',
  'Approfondimenti',
  '',
  true,
  '2024-09-20T15:19:26.000Z'::timestamptz
)
