INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'La 1° autostrada italiana festeggia 100 anni',
  'autostrada-italiana-festeggia-100-anni',
  'L’autostrada italiana ha raggiunto i 100 anni di storia! Il primo tratto autostradale, chiamato Autostrada dei Laghi , fu inaugurato il 21 settembre 1924, dell’ingegnere Piero Puricelli e inaugurata dal Re d’Itali a, Vittorio Emanuele III. Questa arteria collegava Milano con Varese ed è considerata ',
  'L’autostrada italiana ha raggiunto i 100 anni di storia!
Il primo tratto autostradale, chiamato **Autostrada dei Laghi**, fu inaugurato il **21 settembre 1924, **dell’ingegnere**Piero Puricelli**e inaugurata dal Re d’Italia, Vittorio Emanuele III.
Questa arteria collegava Milano con Varese ed è considerata la prima autostrada moderna al mondo, dedicata esclusivamente alla circolazione automobilistica, senza incroci a raso.

Il 22 Settembre c''è stata una celebrazione per questa ricorrenza, si è realizzato di attraversarla di nuovo con un corteo di veicoli storici.

![image](https://www.nolosubito.it/wp-content/uploads/2024/09/autostrada-milanorrr-varese-foto-storiche.jpeg)

In Germania già erano presenti strade riservate solo ai veicoli, ma senza un pedaggio.
La “Autolaghi” nacque quando in tutta Italia c’erano appena 80mila auto e camion, ebbe l’idea di una strada veloce che dalla città di Milano portasse alle zone di **Varese, Como e del Lago Maggiore**, già allora frequentate per il turismo sui laghi. Autolaghi, appunto.

![image](https://www.nolosubito.it/wp-content/uploads/2024/09/autolaghi-1248470.610x431.jpg).   ![image](https://www.nolosubito.it/wp-content/uploads/2024/09/autostrada-milano-varese-foto-storiche.jpeg)

La** costruzione dell’autostrada fino a Varese richiese solo quindici mesi di lavoro**.

A completare il sistema della “Autolaghi” arrivò poi la diramazione da Gallarate a **Sesto Calende**, ampliata solo a fine anni Ottanta con l’inaugurazione della A26 Genova Voltri-Gravellona Toce: questa diramazione serviva a raggiungere la sponda piemontese del Lago Maggiore, quella più prestigiosa, e le montagne dell’Ossola.

A Gallarate e Lainate in origine il **bivio autostradale era “a raso”: un normale incrocio**, dove le auto dovevano dare la precedenza.

Oltre che allo sviluppo del turismo, l’Autolaghi costituì anche un potente **motore di sviluppo anche per l’Alto Milanese**, che ruotava intorno a **Gallarate, Busto e Legnano**.

Negli anni, il sistema autostradale italiano si è espanso enormemente. Oggi ci sono più di **6.700 chilometri di autostrade** in Italia, che collegano città, regioni e persino altri Paesi. In Italia, le autostrade sono prevalentemente a pedaggio.
Dopodiché iniziano a spuntare anche i primi autogrill, punti di ristoro lungo le autostrade, sono diventati una vera e propria istituzione. Il primo nacque nel 1958 e da allora fanno parte del paesaggio autostradale italiano, noti anche per l’alta qualità dei loro prodotti alimentari.

L''autostrada più lunga d’Italia è la **A1** (Autostrada del Sole), che collega Milano a Napoli per un totale di circa **760 chilometri**.',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/09/autostrada-milanorrr-varese-foto-storiche.jpeg',
  true,
  '2024-09-23T09:01:38.000Z'::timestamptz
)
