INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Anche gli operai dell'' Audi si ribellano',
  'anche-gli-operai-dell-audi-si-ribellano',
  'Anche gli operai dell'' Audi si ribellano Come abbiamo scritto precedentemente sia la Volskwagen che per il Gruppo Stellanti stanno avendo gravi perdite nella produzione e, gli operai, stanno scioperando. Ora tocca alla casa Audi di Bruxelles dove gli operai hanno confiscato più di 200 chiavi Audi. H',
  'Anche gli operai dell'' Audi si ribellano
Come abbiamo scritto precedentemente sia la [Volskwagen](https://www.nolosubito.it/curiosita/volkswagen-chiuderebbe-gli-stabilimenti-in-germania/) che per il [Gruppo Stellanti  ](https://www.nolosubito.it/curiosita/gruppo-stellantis-in-crisi/)stanno avendo gravi perdite nella produzione e, gli operai, stanno scioperando.
Ora tocca alla casa Audi di Bruxelles dove gli operai hanno confiscato più di 200 chiavi Audi.

Hanno confiscato  200 chiavi assicurandosi che usciranno dall''impianto di produzione fino a quando non otterranno garanzie sul futuro.  Nell’ambito della manifestazione, i dipendenti hanno preso le chiavi di veicoli finiti e incompleti per chiedere chiarezza sul futuro dello stabilimento belga. Audi ha ordinato la loro immediata restituzione, avvertendo di poter identificare i responsabili grazie alle telecamere a circuito chiuso.

L''azienda automobilistica si trova in una situazione definita "allarmante" dai suoi stessi vertici e a fronte di una concorrenza cinese sempre più aggressiva, soprattutto nel settore delle auto elettriche. In Belgio gli operai hanno deciso di non restare inermi, optando per il braccio di ferro dopo settimane di chiusura dell''impianto. Non solo scioperi ma anche azioni collettive "alternative" siccome non vengono presi in considerazione.

La risposta di Audi non si è fatta attendere: secondo quanto riportato dall''agenzia di stampa Belga, la società ha dichiarato di non voler cedere a quello che considera un ricatto.
Di fronte alle minacce di azioni legali brandite dalla direzione, i sindacati hanno annunciato un incontro nella mattinata di domani per definire una posizione comune. I dipendenti della fabbrica di Forest sono in agitazione da luglio, quando Audi aveva paventato la chiusura del sito a causa della scarsa domanda dei Suv elettrici Q8 e-tron.  Gli operai hanno già interrotto il lavoro nei giorni scorsi, impedendo la ripresa della produzione dopo la pausa estiva.',
  'Approfondimenti',
  '',
  true,
  '2024-09-26T09:52:56.000Z'::timestamptz
)
