INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Nuova Ferrari ma elettrica',
  'ferrari-elettrica',
  'Nuova Ferrari ma elettrica Non è la prima volta che la Ferrari si concentra sull''elettrico ce ne sono stata altre due ma HYBRID, ora invece nel 2025 ne uscirà una completamente 100% elettrica. I primi modelli hybrid ricordiamo sono la Ferrari SF90 Stradale (2019) e Ferrari 296 GTB (2021). La Ferrari',
  'Nuova Ferrari ma elettrica
Non è la prima volta che la Ferrari si concentra sull''elettrico ce ne sono stata altre due ma HYBRID, ora invece nel 2025 ne uscirà una completamente 100% elettrica.
I primi modelli hybrid ricordiamo sono la **Ferrari SF90 Stradale (2019) **e **Ferrari 296 GTB (2021).**

La Ferrari ha annunciato che lancerà la sua **prima auto completamente elettrica nel 2025**. Anche se non sono ancora stati rivelati dettagli precisi sul modello, ci sono alcune informazioni generali su cosa possiamo aspettarci da questo veicolo:

 	- **Performance**: Ferrari ha chiarito che la versione elettrica manterrà le prestazioni elevate e l''esperienza di guida dinamica che caratterizza il marchio. L''auto sarà progettata per offrire non solo potenza, ma anche agilità e maneggevolezza.
 	- **Tecnologia avanzata**: L''auto elettrica Ferrari integrerà le più recenti tecnologie di propulsione elettrica, sfruttando batterie e motori di ultima generazione. È probabile che impiegheranno architetture leggere e ottimizzate per garantire un equilibrio tra prestazioni e autonomia.
 	- **Design**: Ferrari continuerà a puntare su un design iconico e aerodinamico, mantenendo l''estetica distintiva del marchio. L''elettrificazione non comprometterà lo stile riconoscibile delle auto Ferrari.
 	- **Elettrificazione graduale**: Questo veicolo fa parte del piano di elettrificazione graduale di Ferrari.

Ferrari ha promesso che la sua prima elettrica sarà rivoluzionaria e fedele ai valori del marchio in termini di lusso e prestazioni.
Il primo ad averla provata è il presidente della casa del cavallino John Elkann che, durante una puntata un podcast ha descritto la prima guida cosi "*Ho provato la nuova Ferrari elettrica: è incredibile, totalmente diversa da quanto ci si possa aspettare*".
Secondo un''indiscrezione pubblicata da Reuters l''auto potrebbe costare attorno ai 500mila euro. "Per noi, l''auto elettrica è una tela bianca che ci permette di utilizzare nuove tecnologie, provenienti dal mondo elettrico ed elettronico, e di poter davvero creare e progettare un''auto molto diversa. **L''ho guidata ed è incredibile**, sotto tutti i punti di vista. Se ti piace guidare, i brividi e le emozioni che si proveranno su quest''auto saranno semplicemente eccezionali. Dà un enorme ottimismo e coraggio a Ferrari pensare che il nostro futuro non sarà solo con i nostri grandi motori a combustione, ma anche con i motori ibridi che esistono oggi. Non solo nelle corse con il nostro V6 ibrido, ma anche nelle auto sportive e nelle auto elettriche che inizieranno a essere presentate nel 2025".

Sulla prima Ferrari elettrica della storia che sarà costruita nel nuovo stabilimento e-building di Maranello **da inizio 2025** non ci sono ancora informazioni ufficiali, tranne che avrà un "suono autentico", da "vera Ferrari" come ha detto l''Head of product marketing Emanuele Carando.
[Qui](https://www.youtube.com/watch?v=vMMcguEgKdk) un breve video di presentazione.

[rl_gallery id="2061666"]',
  'Notizie',
  '',
  true,
  '2024-10-01T09:50:04.000Z'::timestamptz
)
