INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Tesla e il nuovo Robovan',
  'tesla-e-il-nuovo-robovan',
  'Tesla e il nuovo Robovan Giovedì, all''evento "We Robot" di Tesla tenutosi a Los Angeles, la casa automobilistica ha presentato a sorpresa un nuovo veicolo: il Robovan . Si tratta di un autobus dall''aspetto strano, simile a un aspirapolvere, che Tesla sostiene sarà in grado di guidare in modo autonom',
  '**Tesla e il nuovo Robovan**

Giovedì,  all''evento **"We Robot"** di Tesla tenutosi a Los Angeles, la casa automobilistica ha presentato a sorpresa un nuovo veicolo: il **Robovan**.
Si tratta di un autobus dall''aspetto strano, simile a un aspirapolvere, che Tesla sostiene sarà in grado di guidare in modo autonomo. L''evento era apparentemente incentrato sulla presentazione del Cybercab , un taxi autonomo che Tesla ha pubblicizzato per anni. Il Robovan, nel frattempo, è stata una sorprendente aggiunta dell''ultimo minuto.

![image](https://www.nolosubito.it/wp-content/uploads/2024/10/teslarobovan21.avif)

All''evento mentre gli spettatori esponevano domande, a sorpresa entra il Robovan. Alla domanda specifica - **"Cosa succede se hai bisogno di un veicolo più grande di un Model Y ?"** CEO di Tesla Elon Musk risponde **"Robovan! può trasportare fino a 20 persone, ad esempio una squadra sportiva, o trasportare merci..."**

![image](https://www.nolosubito.it/wp-content/uploads/2024/10/tesla-robovan-1-1000x600-1.jpg)

La presentazione è stata scarsa di dettagli concreti sulle capacità del veicolo, sul prezzo o sulla data di uscita. Quindi molte delle cose importanti sono ancora un mistero. Ciò che sappiamo è che il veicolo a forma di baccello ha porte scorrevoli in vetro, interni luminosi e file di sedili in stile carrozza che si fronteggiano.

Le ruote del Robovan sono nascoste all''interno, dando l''impressione che stia quasi fluttuando a pochi centimetri dal suolo. Come il Cybercab, non sembra avere un volante.
![image](https://www.nolosubito.it/wp-content/uploads/2024/10/Tesla_Robovan.jpg) ![image](https://www.nolosubito.it/wp-content/uploads/2024/10/Robovan_73-e1728619221559.webp)

Vi ricordiamo che la Tesla oltre al Robotaxi - Robovan ma idealizzato e realizzato un vero è proprio Robot che sarà pronto nel 2025.

![image](https://www.nolosubito.it/wp-content/uploads/2024/10/58327e32-818f-5ec8-a0ad-955176750000.avif) Robotaxi

![image](https://www.nolosubito.it/wp-content/uploads/2024/10/maxresdefault.jpg) (progetto) -  ![image](https://www.nolosubito.it/wp-content/uploads/2024/10/We-Robot-Carousel-Slide-3-TeslaBot-Desktop.avif) (realtà)

Qui un breve [video sui progetti futuri](https://www.tiktok.com/@nolosubito/video/7425630027095559456?is_from_webapp=1&sender_device=pc&web_id=7407469281396803105)

Non so se tutto ciò sarà positivo o negativo per l''essere umano, mi immagino tanto il film con Will Smith " I Robot" .

[Tesla](https://www.tesla.com/it_it/we-robot) e i suoi progetti. Voi cosa ne pensate???',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/10/teslarobovan21.avif',
  true,
  '2024-10-11T08:34:29.000Z'::timestamptz
)
