INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Vesuvio Motor Show 2024',
  'vesuvio-motor-show-2024',
  'Vesuvio Motor Show 2024 Il Vesuvio Motor Show 2024 si è svolto a Napoli dall''11 al 13 ottobre, principalmente nella zona di Gianturco, lungo via Brecce a Sant''Erasmo. Questo evento dedicato agli appassionati di motori ha offerto un ingresso gratuito e ha incluso un programma ricco di esposizioni, sp',
  '**Vesuvio Motor Show 2024**

Il *Vesuvio Motor Show 2024* si è svolto a Napoli dall''11 al 13 ottobre, principalmente nella zona di Gianturco, lungo via Brecce a Sant''Erasmo. Questo evento dedicato agli appassionati di motori ha offerto un ingresso gratuito e ha incluso un programma ricco di esposizioni, spettacoli e attività interattive.

Durante i tre giorni, i visitatori hanno potuto ammirare un''esposizione di supercar e hypercar come Ferrari, Lamborghini e Porsche, oltre a moto e auto storiche. Ci sono stati anche simulatori di guida e spettacoli di stuntman. Ovviamente non sono mancati gli stand gastronomici e un''area dedicata ai corsi di guida sicura.

**Antonio Olivieri**, organizzatore dell’evento racchiude le sue emozioni: “Portare tanti bambini a Breccia a Sant’Erasmo è una nostra piccola vittoria per una Montecarlo nella periferia di Napoli. Abbiamo sintetizzato il nostro modo di fare motorsport parlando di Sport, Supercar, Strada, Sicurezza, lavorando in partnership con l’Università Federico II grazie a convegni con i grandi ingegneri del Motorsport di Good Year, McLaren, Porsche. E ancora con la Polizia di Stato abbiamo parlato di sicurezza stradale, abbiamo presentato un’area eventi spettacolare con stuntman di auto e moto. Spettacoli gratuiti a disposizione di grandi e piccolo in un’area di grandi potenzialità di sviluppo”.

Vediamo come si sono svolti questi giorni.
Nella giornata di **Venerdi 11** ci sono stati convegni, guida sicura e Stuntman al pausilipon. Incontro con **Marco Mongelluzzi** collaudatore per parlare di guida sicura e di come prevenire gli incidenti stradali. Esibizione di Alvaro Dal Farro, stuntman su motocicletta che ha portato le sue acrobazie nei corridoi dell’ospedale pediatrico Pausilipon. [Alvaro Dal Farro](https://www.facebook.com/vesuvio.motorshow/posts/pfbid02wo23WVNPBKYPbZ2ABssa2Mg7SxTSM43ipA7fDMAkBJF8gjShQTTL7iz3E4RNK4gol?locale=it_IT), è da anni che si occupa di progetti socialmente utili.
A seguire interviste e dirette social con i vari fondatori e invitati.

**Sabato 12 - **Via alle Sfide in Brecce a Sant’Erasmo
Taglio del nastro con il Sindaco di Napoli, Gaetano Manfredi, l’Assessore alle politiche culturali Teresa Armato, l’assessore della Municipalità Maria Caniglia, il testimonial Paolo Scudieri, la Famiglia Pugliese, proprietà del Gold Tower, il responsabile commerciale di Vega Luxury Ettore Pirozzi.
Gli stunt riding, i car show con predator kart, lo Stunt Show man Salvatore Maraffino, le moto con Alvaro Dal Farra e Marco Barzy, i simulatori. Area Food con “Nennella”, “Puok”, “Ciccio’s Corner” e un punto bar; la musica e le interviste di Radio Punto Zero. La sera ingresso su invito per i proprietari delle auto che partecipano al Vesuvio Motor Show Exclusive, lo speciale Tour dedicato ai proprietari delle auto su Terrazza Ramé dove è esposta la Formula3 del Team Valentino Racing che ha vinto il campionato Italiano 2022 e 2023, terza nell’Europeo 2023 con al volante Valentino Carofano.

Domenica 13 - Il Kart– Sessanta Supercar in esposizione via Brecce a Sant’Erasmo

Dalla mattina sono partiti spettacoli , car show e scuola di  “kart Academy for Winners” con gli stuntman.
Nel pomeriggio. invece, in esposizione sessanta le supercar lungo via Breccia a Sant''Erasmo in particolare le Ferrari, Lambirghini, Porsche, Lancia Delta, Alfa Romeo a seguire anche le moto come la Honda. Presente anche il nuovo marchio stellantis Leapmotor  con le sue due prosposte C10 e T03.
Sito ufficiale dell''evento [Vesuvio Motor Show 2024](https://www.vesuviomotorshow.it/)',
  'Notizie',
  '',
  true,
  '2024-10-14T08:33:27.000Z'::timestamptz
)
