INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Nuovo marchio - Leapmotor',
  'nuovo-marchio-leapmotor',
  'L''obiettivo è quello di non limitarsi alle auto elettriche, ma esplorare anche soluzioni per la guida autonoma.',
  '**Nuovo marchio - Leapmotor**

Iniziamo con presentarvi il marchio Leapmotor, è un''azienda cinese fondata nel 2015 da Zhu Jiangming, ingegnere elettronico di lunga esperienza specializzata nello sviluppo di veicoli elettrici intelligenti.
L''obiettivo è quello di non limitarsi alle auto elettriche, ma esplorare anche soluzioni per la guida autonoma.

Proprio in relazione alla guida autonoma l’azienda si fa notare. Nel 2018 lancia il suo chip “Lingxin 01”, pensato per portare la potenza dell’Intelligenza Artificiale a bordo dei veicoli elettrici. Una soluzione sviluppata in collaborazione con Dahua Technology, altra importante azienda del Zhejiang.
Successivamente nel 2019 viene lanciato sul mercato cinese il primo modello, il coupé elettrico a 2 porte Leapmotor S01, il cui prototipo è mostrato in anteprima al salone di [Guangzhou](https://it.wikipedia.org/wiki/Guangzhou) all''inizio del 2018. A quel tempo, la società aveva raccolto circa 380 milioni di capitale ed aveva iniziato la costruzione della sua prima fabbrica.
![image](https://www.nolosubito.it/wp-content/uploads/2024/10/leapmotor-s01-specs-21-scaled-1.jpeg)
Successivamente nel 2020 Leapmotor lancia il secondo veicolo elettrico, la **city car** [T03](https://www.nolosubito.it/?post_type=product&s=leapmotor).
![image](https://www.nolosubito.it/wp-content/uploads/2024/10/leapmotor-t03-v1-851150.jpeg)
Nello stesso anno debutta il terzo veicolo elettrico, la crossover **C11**.
![image](https://www.nolosubito.it/wp-content/uploads/2024/10/leapmotor-c11-anteriore.webp)

Ad agosto 2023 la casa presenta una nuova piattaforma modulare, dedicata alla produzione di veicoli elettrici.

Nell''ottobre 2023 Stellantis acquista il 20% di Leapmotor. Sempre nell''ottobre 2023 crea la joint venture "Leapmotor International" con Stellantis, nella quale quest''ultima detiene il 51% e la Leapmotor il 49%, Detiene l''esclusiva dell''export e del mercato al di fuori della Cina.

Insomma in pochissimi anni 4/5 anni il marchio Leapmotor si è fatto strada  anche in Europa pubblicizzando le due vetture [CITY-CAR T03](https://www.nolosubito.it/veicoli/auto/leapmotor-t03-2/) e il [SUV C10 ](https://www.nolosubito.it/veicoli/auto/leapmotor-c10-style/)i primi modelli commercializzati in Europa.

![image](https://www.nolosubito.it/wp-content/uploads/2024/10/First-Batch-of-Leapmotor-Electric-Vehicles-Shipped-from-China-to-Europe.jpeg)
Inoltre al Salone di Parigi è stata presentata la nuova versione **B10 **compatto disponibile inzialmente solo con powertrain elettrico.

![image](https://www.nolosubito.it/wp-content/uploads/2024/10/06-Leapmotor-B10-kvED-U60362896194pRB-600x313@IlSole24Ore-Web.avif)',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/10/leapmotor-s01-specs-21-scaled-1.jpeg',
  true,
  '2024-10-15T10:40:45.000Z'::timestamptz
)
