INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Stop alla produzione di auto benzina e diesel',
  'stop-alla-produzione',
  'Jean-Philippe Imparato (Amministratore delegato dell'' Alfa Romeo dal 19 gennaio 2021, è stato anche amministratore delegato di Peugeot) ha dichiarato che l''obiettivo di Stellantis è quello di raddoppiare la quota di vendite di auto elettriche, arrivando al 24% nel corso del 2025. Il problema però è ',
  'Stop alla produzione di auto benzina e diesel
Già ci occupammo, in un articolo precedente, delle auto con poca richiesta e quindi produzione ma erano a [metano](https://www.nolosubito.it/curiosita/metano/) infatti, nel 2035, sarà impedita la produzione.
Questa volta sembra toccare all''alimentazione Benzina e Diesel ma il motivo è un altro.
A partire dal 2025, il limite di emissioni medie di CO2 per i veicoli venduti nell''Unione Europea sarà fissato a 95 g/km. Questo regolamento rappresenta una sfida significativa per molti produttori di automobili, soprattutto quelli che dipendono ancora fortemente dai veicoli con motori a combustione interna. Superare questo limite comporterà il pagamento di pesanti sanzioni, il che sta spingendo i costruttori a sollecitare l''UE per un possibile rinvio o per un allentamento delle normative.Per rispettare tale soglia, i produttori dovranno investire ulteriormente in tecnologie a basse emissioni, come i veicoli elettrici e ibridi. Tuttavia, molti costruttori ritengono che la transizione sia troppo rapida e difficile da sostenere senza impatti significativi sui costi e sulla competitività.

Le case automobilistiche stanno cercando di ottenere una proroga, sostenendo che non tutte le regioni e i mercati sono pronti per un''adozione massiccia di veicoli elettrici. La questione rimane delicata e sarà fondamentale vedere se l''UE deciderà di mantenere il limite del 2025 o di apportare modifiche per facilitare la transizione.
Jean-Philippe Imparato (Amministratore delegato dell'' [Alfa Romeo](https://it.wikipedia.org/wiki/Alfa_Romeo) dal 19 gennaio 2021, è stato anche amministratore delegato di [Peugeot) ](https://it.wikipedia.org/wiki/Peugeot)ha dichiarato che l''obiettivo di Stellantis è quello di raddoppiare la quota di vendite di auto elettriche, arrivando al 24% nel corso del 2025. Il problema però è la domanda, sempre troppo bassa in molti Paesi europei. "Dato che produciamo solo veicoli in base all''ordine del cliente, assembleremo tanti motori a combustione interna quanti ne saranno necessari per mantenere la quota di **veicoli elettrici** al livello richiesto", il tutto spingendo sulla vendita di auto elettriche.  Ovviamente per spingere tale mercato, ci saranno degli incentivi da parte del gruppo Stellantis.

A tal proposito sono stante lanciate nel mercato Europeo 2 vetture 100% elettriche, un SUV e CITYCAR, parliamo del marchio Leapmotor ([qui un articolo sulle autovetture](https://www.nolosubito.it/curiosita/nuovo-marchio-leapmotor/)) e qui un [video ](https://www.tiktok.com/@nolosubito/video/7428251870608559392?is_from_webapp=1&sender_device=pc&web_id=7407469281396803105) ** **',
  'Notizie',
  '',
  true,
  '2024-10-22T08:53:38.000Z'::timestamptz
)
ON CONFLICT (slug) DO UPDATE SET
