INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Federali aprono un’indagine sulla Tesla e il Full Self-Driving',
  'tesla-problemi-federali',
  'Negli Stati Uniti sembra che i federali hanno aperto varie indagini sulle auto Tesla per il Full Self-Driving, come mai? Come già sappiamo, in un articolo precedente, la casa automobilistica Tesla ha ideato e sviluppato il Full Self-Driving (FSD) per i suoi veicoli elettrici. Questo sistema permette',
  'Negli Stati Uniti sembra che i federali hanno aperto varie indagini sulle auto Tesla per il Full Self-Driving, come mai?

Come già sappiamo, in un articolo precedente, la casa automobilistica Tesla ha ideato e sviluppato il **[Full Self-Driving](https://www.nolosubito.it/curiosita/le-auto-del-futuro-parleranno-tra-loro/) (FSD)** per i suoi veicoli elettrici. Questo sistema permette di avere una guida autonoma senza bisogno dell''intervento del conducente.
Ma cosa è successo negli Stati Uniti addirittura con i Federali ovvero la **Nhtsa** (National Highway Traffic Safety Administration)?

Purtroppo sono state ricevute già 4 segnalazioni di incidenti tra cui uno fatale. La notizia arriva dall''ente americano per la sicurezza stradale, dove questi incidenti si sono verificati durante la guida "autonoma" con scarsa visibilità (nebbia, polvere sospesa e riverbero del sole), ed è proprio per questo motivo che è stato investito e ucciso un pedone.

Le auto coinvolte sono le elettriche Model S, Model X, Model 3,
![image](https://www.nolosubito.it/wp-content/uploads/2024/10/tesla-neuwagen-sofort-verfugbar-model-s-model-3-model-x-model-y-723098.webp)
e tutti i Cybertruck ( quest''ultimo già soggetto a numerosi richiami). ![image](https://www.nolosubito.it/wp-content/uploads/2024/10/2024-tesla-cybertruck-115-65e8945de87ba.avif)

Al momento, però, non sono richiami ufficiali con scopo sull'' indagine di concentrarsi sul sistema FSD soprattutto sulla visibilità ridotta con condizioni atmosferiche. Cercare di capire se realmente il problema era la "poco visibilità" o errori al software.

Il problema nasce nel momento in cui Elon Musk sta sviluppando mezzi con solo 2 posti di guida completamente autonomo, senza volante né pedali, (qui un [articolo](https://www.nolosubito.it/curiosita/tesla-e-il-nuovo-robovan/) e [video](https://www.tiktok.com/@nolosubito/video/7428251870608559392?is_from_webapp=1&sender_device=pc&web_id=7407469281396803105) sull''argomento) chiamato Robotaxi/Cybercab. Non solo ma anche il Robovan un "pulmino" da 14 posti con le stesse caratteristiche.

Saranno in grado di essere al 100% sicuri? Precisiamo che anche con la guida del conducente non è del tutto sicura, purtroppo guasti o distrazioni sono motivo di scontri molte spesso anche fatali, però sicuramente non può essere paragonato ad una guida "autonoma" siccome dovrebbe facilitare e dare più sicurezza.
Ovviamente credo che sia meglio e prudente che il conducente sia sempre attento e pronto a prendere il controllo del volante.

Sicuramente i mezzi autonomi per poter circolare negli Stati Uniti devono avere ufficialmente l''autorizzazione proprio della Nhtas, anche per i futuri progetti scritti poc''anzi, quindi un cane che si morde la coda.',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/10/tesla-neuwagen-sofort-verfugbar-model-s-model-3-model-x-model-y-723098.webp',
  true,
  '2024-10-24T08:13:36.000Z'::timestamptz
)
