INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Polestar 4, la prima auto senza lunotto',
  'polestar-4',
  'La Polestar ha consegnato in Italia i primi esemplari della Suv-coupé elettrica 4 , del marchio svedese, che si distingue per l’assenza del lunotto posteriore (sostituito da una telecamera). "L’accoglienza sul mercato italiano è una chiara dimostrazione dell’entusiasmo e della fiducia che i nostri c',
  'Avete mai visto un''auto senza il suo lunotto? Da quest''anno è stato possibile, vi presentiamo la prima in assoluto la Polestar 4.

![image](https://www.nolosubito.it/wp-content/uploads/2024/10/13007_large.jpeg)

La Polestar ha consegnato in Italia i primi esemplari della **Suv-coupé elettrica 4**, del marchio svedese, che si distingue per l’assenza del lunotto posteriore (sostituito da una telecamera). "L’accoglienza sul mercato italiano è una chiara dimostrazione dell’entusiasmo e della fiducia che i nostri clienti ripongono nel nostro marchio", commenta Dimitris Chanazoglou, Managing Director della Casa svedese.
Con un design sportivo e moderno, il lunotto viene sostituito da una videocamera che proietta le immagini nel display interno, migliorando la visibilità e permettendo maggiore spazio per i passeggeri.
![image](https://www.nolosubito.it/wp-content/uploads/2024/10/1702461867-00-polestar-4-rear-view-open-graph-row.avif)  ![image](https://www.nolosubito.it/wp-content/uploads/2024/10/ffiu0q4w5wya1-e1729849139315.webp)

Uno schermo ad alta definizione consente di mostrare cosa succede con più precisione e nel dettaglio al guidatore, grazie alla doppia telecamera al tetto: in tempo reale si ha l’immagine di una qualità perfetta, anche con bassa luminosità.

Gli interni sono realizzati con materiali eco-compatibili, inclusi tessuti derivati da materiali riciclati. La Polestar 4 offre una potenza di circa 544 CV nella versione a doppio motore, dotata di una batteria di circa 102 kWh, può raggiungere un''autonomia stimata intorno ai 560 km. Supporta la ricarica rapida DC, permettendo di raggiungere una ricarica dell''80% in circa 30 minuti. Inoltre il pacchetto di assistenza alla guida include funzioni avanzate come la guida autonoma di livello 2, che include cruise control adattivo, mantenimento della corsia, e una guida semi-autonoma in autostrada.

Particolarità per gli amanti della montagna, l’Head Display con modalità “Neve” per non essere infastiditi durante i tracciati bianchi.

Polestar 4 promette un’esperienza di guida premium combinata con un impegno verso la sostenibilità e le prestazioni oltre ad avere un design molto accattivante. Il lancio in Italia entro fine 2024, punta ad affermarsi come alternativa sostenibile e di fascia alta.',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/10/13007_large.jpeg',
  true,
  '2024-10-25T09:48:31.000Z'::timestamptz
)
