INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Vuoi la Batmobile? da oggi puoi averla',
  'batmobile-in-vendita',
  'Hai sempre desiderato acquistare e guidare la Batmobile ? Da oggi potrai, se hai 3 milioni di dollari ovvero circa 2,7 milioni di euro. Per il 85° anniversario di Batman. Di versioni Batmobile ne abbiamo tante ma solo una in particolare sarà messa in vendita, ovvero quella della saga diretta da Chri',
  'Hai sempre desiderato acquistare e guidare la **Batmobile**? Da oggi potrai, se hai 3 milioni di dollari ovvero circa 2,7 milioni di euro.
Per il 85° anniversario di Batman.

Di versioni Batmobile  ne abbiamo tante ma solo una in particolare sarà messa in vendita, ovvero quella della saga diretta da **Christopher Nolan **(2005-2012)

![image](https://www.nolosubito.it/wp-content/uploads/2024/11/batmobile-1-1.png)

Per chi non la conoscesse la **Batmobile** è l''automobile personale del supereroe della [DC Comics](https://it.wikipedia.org/wiki/DC_Comics) [Batman](https://it.wikipedia.org/wiki/Batman). La macchina ha subito l''evoluzione dal fumetto alla televisione al film. Tenuta nella [Batcaverna](https://it.wikipedia.org/wiki/Batcaverna), a cui si accede attraverso alcune entrate segrete, la Batmobile è un veicolo pieno di strumenti e oggetti per le attività anticrimine di Batman.

Per 10 fortunati potranno acquistare le altrettante riproduzioni della **Batmobile in versione Tumbler **realizzate da Action Vehicle Engineering, la quale ha stipulato un accordo con la Warner Bros, per 3 milioni di dollari.
Sarà un’auto a benzina, perfettamente funzionante e curata in ogni dettaglio. Peccato che non sia omologabile per l''uso su strada ovviamente.

Un Suv medio-alto  lunga 4,64 mt e larga 2,82 mt con un peso di 2,5 tonnellate (peso accettabile per un Suv). Con 532 cavalli, cambio automatico a 4 rapporti.  Aria condizionata rivestimento in Alcantara col. nero fornito anche di GPS, disponibilità solo con guida a sinistra. 2 porte e con cinture da corsa a 5 punti.

Per averla bisogna registrarsi sul [sito ufficiale dell''asta](https://brucewaynex.com/pages/tumbler) e inserire le informazioni personali. Successivamente si viene ricontattati dall''organizzazione, che verificherà le ‘condizioni economiche’. In un secondo momento avverrà la selezione dei 10 fortunati, estratti a sorte dal sito. Stando alle poche informazioni disponibili, la consegna della Batmobile è stimata in 15 mesi, con l''acquirente che la riceverà direttamente a casa, con tanto di numero di serie unico sulla carrozzeria.',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/11/batmobile-1-1.png',
  true,
  '2024-11-07T10:22:26.000Z'::timestamptz
)
