INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'La fabbrica Dongfeng non aprirà in Italia',
  'fabbrica-dongfeng-non-aprira-in-italia',
  'Si dice che la fabbrica Dongfeng non aprirà più in Italia, ma non è chiaro se sia una scelta strategica della casa automobilistica cinese. Dongfeng Motor Corporation , spesso abbreviata come Dongfeng , è una delle più grandi e importanti case automobilistiche della Cina, in un articolo scrivemmo già',
  'Si dice che la fabbrica Dongfeng non aprirà più in Italia, ma non è chiaro se sia una scelta strategica della casa automobilistica cinese.

**Dongfeng Motor Corporation**, spesso abbreviata come **Dongfeng**, è una delle più grandi e importanti case automobilistiche della Cina, in un articolo scrivemmo già di loro [https://www.nolosubito.it/curiosita/dongfeng/](https://www.nolosubito.it/curiosita/dongfeng/) .
Fondata nel 1969, ha sede a Wuhan, nella provincia di Hubei. Dongfeng è una delle "Big Four" dell''industria automobilistica cinese, insieme a SAIC Motor, FAW Group e Changan Automobile.

Dongfeng, grande produttore cinese di auto e veicoli commerciali, ha sempre mostrato interesse per i mercati esteri. Tuttavia, la decisione di non aprire in Italia potrebbe essere dovuta alla competizione nel settore europeo, alle regolamentazioni locali, alle preferenze dei consumatori o a sfide logistiche.

Il governo di Pechino starebbe infatti facendo pressione sulle sue case automobilistiche per farle smettere di cercare nuovi siti di produzione in **Europa**, almeno fino a quando le trattative sui sui dazi sono in corso.

I rapporti con il governo Meloni sono rallentati a causa delle richieste del costruttore cinese e dei dazi UE sulle auto elettriche cinesi, bloccando temporaneamente il progetto discusso nelle ultime settimane.A luglio, il ministro dell’Industria e del Made in Italy Adolfo Urso era volato in Cina per incontrare i dirigenti dell’azienda. Tuttavia, secondo le fonti di *Bloomberg*, il governo cinese (che possiede la Dongfeng Motor Group) ha chiesto alla casa automobilistica di **non procedere**.

Oltre a Dongfeng, anche Changan ha annullato l''evento previsto a Milano per il lancio in Europa, probabilmente a causa delle trattative in corso.

Si dovrà, dunque, attendere i prossimi giorni per eventuali sviluppi e capire se il progetto per la fabbrica Dongfeng possa ritenersi definitivamente accantonato.

Non sappiamo però se tutto questo avrà i suoi benefici in Italia o meno, voi cosa ne pensate??',
  'Notizie',
  '',
  true,
  '2024-11-14T11:24:17.000Z'::timestamptz
)
