INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Giornata mondiale vittime della strada',
  'giornata-mondiale-vittime-della-strada',
  'vittime della strada Giornata mondiale vittime della strada Ogni anno, ogni giorno centinaia/migliaia di persone perdono la vita a causa di incidenti stradali. Dal 2021 al 2024 ci sono stati un aumento di incidenti da 151.875 incidenti con 2.875 decessi ai 165.889 incidenti e 3.159 morti e, in base ',
  'vittime della strada
Giornata mondiale vittime della strada

Ogni anno, ogni giorno centinaia/migliaia di persone perdono la vita a causa di incidenti stradali.
Dal 2021 al 2024 ci sono stati un aumento di incidenti da **151.875 incidenti** con **2.875 decessi **ai **165.889 incidenti e 3.159 morti **e, in base a una ricerca gli incidenti stradali sono la principale causa di morte tra i giovani di età compresa tra i 5 e i 29 anni.

La causa PRINCIPALE e sicuramente la distrazione alla guida e/o pedone.
**- Distrazioni: **Distrarsi anche solo 10 secondi ne vale della tua vita e di chi ti circonda. Nelle cause più comuni della "distrazione" è sicuramente l''uso dello smartphone che, ancora tutt''oggi , è luna delle cause principali di incidenti e decessi.
Quante volte ci siamo imbattuti in discussioni o incidenti? Sono stata tamponata mentre facevo attraversare un''anziana sulle strisce pedonali: un uomo distratto dal cellulare non si è accorto che ero ferma da qualche minuto. Un''altra volta, in autostrada, ho notato un''auto che rallentava e sbandava continuamente da 10 minuti. Pensavo che il conducente avesse sonno, ma in realtà stava guardando le storie sui social. Quando ho suonato per avvertirlo, mi ha pure mandato a quel paese.

- **Eccesso di velocità: **il secondo fattore ma per me viene affiancato al primo, è sicuramente l''eccesso di velocità sia in città che in autostrada. In città soprattutto che bisogna rispettare i limiti di 30km/h(in presenza di scuole) e 50km/h, purtroppo vedo sempre più persone che "per la fretta" corrono, devono correre. Ancora di più i ragazzi che per fare "colpo" accelerano senza pensare alle conseguenze. In autostrada stesso discorso, la mia domanda è **"ma dove correte tutti?!"**

- **Guida in stato di ebbrezza o sotto l''effetto di sostanze stupefacenti: **qui purtroppo non c''è mai fine... In diverse regioni le infrazioni per guida in stato di ebbrezza sono aumentate del 20% rispetto all''anno precedente, mentre per le assunzioni di varie droghe, il numero di conducenti risultati positivi ai controlli su strada è in crescita, anche se non abbiamo ancora statistiche complete e definitive. Questi dati mostrano come la guida in stato di ebbrezza o sotto l''effetto di sostanze stupefacenti rimanga una problematica rilevante, richiedendo interventi di sensibilizzazione e maggiori controlli da parte delle autorità.

- **Mancato utilizzo di dispositivi di sicurezza: **Quanti di voi indossano realmente la cintura di sicurezza? e perchè non la indossate? a cosa pensate? Abbiamo effettuato una ricerca online per individuare le città con la più alta percentuale di persone che non utilizzano le cinture di sicurezza: La prima è Bari con il 45%, a seguire Milano 20%, Roma 19% e Padova con il 14%.  Vi voglio elencare delle cronache recenti:

 	- Un urto violento che non ha lasciato scampo a una ragazza, dove è stata brutalmente sbalzata via dall''abitacolo,  inutile i soccorsi...
 	- Una bambina di soli 3 anni, Aurora, dormiva in braccio alla madre è morta sul colpo...
 	- In 4 dentro a una Smart fortwo, perde la vita una bimba di 8 anni...

Potrei andare avanti all''infinito e non finirla più, cosa vi spinge a non mettere la cintura di sicurezza? siete consapevoli che state rischiando la vostra vita?

- **Guida senza patente: **Si tratta di una violazione grave che, secondo i dati raccolti dalle autorità stradali, è ancora una problematica diffusa. Nonostante le sanzioni e i controlli, la guida senza patente contribuisce significativamente agli incidenti stradali, spesso associandosi a comportamenti irresponsabili come l''eccesso di velocità o la guida sotto l''influenza di sostanze. Purtroppo molto spesso sento al telegiornale incidenti causati da un conducente in stato di ebrezza e senza patente...

Nonostante la super tecnologia sulle nostre auto i rischi di incidenti e decessi sono sempre alti, e ogni anno aumentano sempre di più. Purtroppo nonostante sono pochi i punti fondamentali c''è sempre qualcuno che non rispetta e quel qualcuno rischia non solo la sua vita ma anche quella di un''altra persona (l''altra persone dove rispetta tutti i 4 punti).

Mi chiedo la vostra vita vale cosi poco? E'' più importante vedere la storia o un messaggi anzichè guardare la strada? Correte per andare dove? Guidate ubriachi pensando di riuscire a essere lucidi e pronti ai riflessi?Perchè non indossate l cintura di sicurezza, cosa vi costa indossarla?

A voi i commenti...
vittime della strada',
  'Notizie',
  '',
  true,
  '2024-11-18T09:37:39.000Z'::timestamptz
)
