INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Parola chiave? Innovazione',
  'innovazione',
  'Parola chiave? Innovazione. "E'' con l''innovazione che batteremo la crisi Europea", un messaggio forte e chiaro per il mondo automobilistico citato da Andrea Casaluci. Secondo l''Amministratore Delegato di Pirelli solo con l''innovazione Europa può essere di nuovo leadership in campo automobilistico e ',
  'Parola chiave? **Innovazione.**

"E'' con l''innovazione che batteremo la crisi Europea", un messaggio forte e chiaro per il mondo automobilistico citato da Andrea Casaluci.
Secondo l''Amministratore Delegato di Pirelli solo con l''innovazione Europa può essere di nuovo leadership in campo automobilistico e recuperare lo svantaggio accumulato nei confronti dei produttori cinesi.

- Chi è Andrea Casaluci?
Andrea Casaluci è l''attuale CEO di Pirelli, incarico che ricopre dall''agosto 2023. Laureato in ingegneria al Politecnico di Milano, ha alle spalle una carriera ventennale all''interno dell''azienda, durante la quale ha assunto ruoli di crescente responsabilità in diverse funzioni e Paesi. Prima della sua nomina come amministratore delegato, è stato General Manager dal 2018. Sotto la sua guida, Pirelli si concentra su innovazione tecnologica e sostenibilità.

L''innovazione che si riferisce **Casaluci, **è quella che sta facendo **Bicocca **con il** Cyber Tyre**.
Il progetto **Cyber Tyre**, sviluppato da Pirelli in collaborazione con Bosch e altri istituti come il Politecnico di Milano e quello di Torino, continua a rappresentare un''avanguardia nella tecnologia dei pneumatici intelligenti. Questi pneumatici hanno sensori che inviano in tempo reale dati alla centralina, ottimizzando ABS, ESP e controllo di trazione in base alle condizioni stradali e allo stile di guida. Questa tecnologia mira a migliorare sicurezza, efficienza e comfort di guida​.
Qui un breve video dello sviluppo [https://www.youtube.com/watch?v=XJFIRMfo5sM&t=27s ](https://www.youtube.com/watch?v=XJFIRMfo5sM&t=27s)

![image](https://www.nolosubito.it/wp-content/uploads/2024/11/163625145-0d7c09b6-522d-457f-9059-fd1d4084d08e.jpeg)

In un''intervista su Quattroruote, Andrea Casaluci di Pirelli ha dichiarato di non essere preoccupato per il mercato, se non per quello italiano ed europeo.

Gli viene anche chiesto se l''Europa può ancora recuperare, la risposta è si! Ma deve avere una mano dai nostri "politici" affinché le leggi tutelino lo sviluppo competitivo. Purtroppo per il momento i politici hanno pensato che il mercato Cinese potesse aiutare il mercato Italiano, ma non vediamo buoni risultati.

Voi cosa ne pensate?',
  'Approfondimenti',
  'https://www.nolosubito.it/wp-content/uploads/2024/11/163625145-0d7c09b6-522d-457f-9059-fd1d4084d08e.jpeg',
  true,
  '2024-11-20T10:06:14.000Z'::timestamptz
)
