INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'EX Dipendente Mercedes distrugge 50 veicoli',
  'ex-dipendente-mercedes-distrugge-50-veicoli',
  'Mercedes La notizia non è nuova sono passati un paio di anni quando un ex dipendente 38enne della Mercedes in Spagna, a Vitoria , decide di vendicarsi. In una notte tra il 30 e 31 Dicembre ex dipendente si presenta con un caterpillar e ha distrutto ben 69 veicoli commerciali , causando un danno pari',
  'Mercedes
La notizia non è nuova sono passati un paio di anni quando un ex dipendente 38enne della Mercedes in Spagna, a **Vitoria**, decide di vendicarsi.

In una notte tra il 30 e 31 Dicembre ex dipendente si presenta con un caterpillar e ha **distrutto** ben **69 veicoli commerciali**, causando un danno pari a **2 milioni di euro**.

[video width="636" height="360" mp4="https://www.nolosubito.it/wp-content/uploads/2024/11/Trabajador-DESPEDIDO-de-MERCEDES-ataca-fabrica-con-un-TRACTOR-Multiples-destrozos-I-DESPEDIDO-I.mp4"][/video]

Secondo quanto riportato dai colleghi spagnoli di Periodismo del Motor l’atto vandalico sarebbe avvenuto subito dopo lo scoccare della mezzanotte del **31 dicembre** scorso, quando gli uomini di guardia presso la fabbrica Mercedes si sono accorti che il 38enne – dopo aver **divelto la cancellata** - **stava distruggendo alcuni veicoli parcheggiati**.

Da quanto è emerso dopo le indagini della Polizia locale, l’uomo è risultato un **ex dipendente** dello stabilimento, che proprio diversi anni fa terminò il suo rapporto di lavoro in maniera non proprio serena con la stessa Casa tedesca. Dinamica che sembra aver causato la spropositata reazione.

Oltre a ciò, l''uomo, non contento dei danni provocati ai veicoli commerciali presenti nel parcheggio, **ha provato a dirigersi verso la linea di produzione** per cercare di provocare ulteriori danneggiamenti. Per fortuna la Polizia è riuscita ad intervenire in tempo, fermandolo poco prima che riuscisse ad entrare all’intero della fabbrica.

I piani del 38enne erano ancora più distruttivi: l''uomo, con lo stesso mezzo, voleva anche arrivare all''interno della fabbrica per danneggiare anche l''intero impianto di produzione. Alla fine, però, la sicurezza interna e gli uomini della Ertzaintza, la polizia basca, sono riusciti a fermarlo. L''uomo è stato arrestato, e con un valore stimato medio di circa 40mila euro a furgone, il totale dei danni causati raggiunge e supera i due milioni di euro.',
  'Notizie',
  '',
  true,
  '2024-11-21T09:35:15.000Z'::timestamptz
)
