INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'GPL sempre più popolare',
  'gpl-sempre-piu-popolare',
  'GPL sempre più popolare Ormai sempre più persone stanno scegliendo le auto Hybrid e non solo a tenere testa c''è anche il GPL. La sigla GPL sta per gas di petrolio liquefatti : a temperatura ambiente, una pressione di pochi bar basta per portarli allo stato liquido, riducendone drasticamente il volum',
  '**GPL sempre più popolare**

Ormai sempre più persone stanno scegliendo le auto Hybrid e non solo a tenere testa c''è anche il GPL.
La sigla GPL sta per **gas** di **petrolio liquefatti**: a temperatura ambiente, una pressione di pochi bar basta per portarli allo stato liquido, riducendone drasticamente il volume. È per questo che una piccola bombola riesce a garantire centinaia di km di autonomia. Esso una miscela di idrocarburi, in massima parte propano e butano.

Già in un articolo precedente vedemmo quale carburante sta "scomparendo" dalla circolazione se siete curiosi qui l''articolo  [https://www.nolosubito.it/curiosita/stop-alla-produzione/](https://www.nolosubito.it/curiosita/stop-alla-produzione/)

Nonostante alcune alimentazioni come il [metano  (qui un articolo a riguardo)](https://www.nolosubito.it/curiosita/metano/)  sia finita la sua era, al contrario il GPL sembra essere vivo e vegeto più che mai! Per il mercato sembra nel 2023 siano salite del 3,5% rispetto all''ano 2016. Nonostante ciò però Stellantis decide di sacrificare il gas rispetto all''elettrico cancellando uno dei punti di forza della Fiat, a pensarci bene, è Renault a non preoccuparsene, non essendo parte del gruppo Stellantis, dando via libera alla produzione di auto GPL così come anche la DACIA.

Infatti la Renault proprio in questi giorni ha pubblicato un post su [instagram ](https://www.instagram.com/p/DCoG0EotPC3/) dove, in un post, omaggia la CLIO ECO-G.

Ecco alcuni miti da sfatare per quanto riguarda questa interessante soluzione:

- **Non si può parcheggiare nei parcheggi chiusi o garage sotterranei**
**Falso.** DaL 2021 tutti gli impianti a GPL sono dotati di misure di sicurezza che consentono di parcheggiare serenamente almeno fino al primo piano interrato delle autorimesse.

-**Con la bombola del GPL perdo spazio nel bagagliaio**
**Falso.** Il GPL trova spazio in un serbatoio posizionato al posto della ruota di scorta. Quello che si perde è quindi la possibilità di rimediare ad una foratura – ma c’è da dire che tutti i modelli in commercio ormai sono dotati di kit di riparazione.
**- In caso d’incidente si rischia l’esplosione**
**Falso.** Tutti i serbatoi di ultima generazione sono assemblati con materiali molto solidi e al pari delle autovetture vengono sottoposti a veri e propri “crash test” per provarne la resistenza. Inoltre i serbatoi di GPL vengono riempiti all’80% della capacità abbattendo così il rischio di compressione.
**-Le auto a GPL sono meno divertenti da guidare**
**Falso.** La tecnologia ha fatto passi da gigante e le auto alimentate a GPL sfruttano sistemi di iniezione con un iniettore per cilindro. In questo modo il GPL arriva molto vicino alle valvole di aspirazione e garantisce pressoché le stesse prestazioni degli altri tipi di carburante.
**Vantaggi?**
I costi sono decisamente inferiori rispetto alla benzina. Essendo derivato dal petrolio, difficilmente subisce rincari sul prezzo. Il suo costo al momento è di €0,75 e €0,85 euro al litro, ma lo si può trovare anche a €0,69. L''impianto GPL si può tranquillamente installare anche in un secondo momento il costo varia dai €700 ai €2.000 dipende dal tipo di vettura, impianto ecc.',
  'Notizie',
  '',
  true,
  '2024-11-22T10:25:43.000Z'::timestamptz
)
