INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Nuovo Iveco eMoovy',
  'nuovo-iveco-emoovy',
  'Nuovo Iveco eMoovy fratellino del Daily Il nuovo Iveco eMoovy è stato presentato ufficialmente al salone IAA Transportation 2024 a Hannover. Secondo le informazioni disponibili, la sua commercializzazione è prevista per il 2025 , anche se non è stata specificata una data esatta. La robusta struttura',
  'Nuovo Iveco eMoovy fratellino del Daily

Il nuovo **Iveco eMoovy** è stato presentato ufficialmente al salone IAA Transportation 2024 a Hannover. Secondo le informazioni disponibili, la sua **commercializzazione è prevista per il 2025**, anche se non è stata specificata una data esatta.
La robusta struttura del telaio dell''IVECO eMoovy consente di trasportare carichi utili pesanti , offrendo la capacità di carico tipica di veicoli di più grande dimensione. Infatti, può trasportare fino a 1.500 kg.

![image](https://www.nolosubito.it/wp-content/uploads/2024/11/IVECO_eMoovy_my24_amb_people_1428-300x215.jpeg)

**eMoovy** è stato presentato come un veicolo commerciale leggero completamente elettrico, sviluppato in collaborazione con Hyundai. Questo modello si inserisce nella gamma tra 2,5 e 3,5 tonnellate, con un design modulare pensato per adattarsi a diversi utilizzi, come furgoni, cassoni o autonegozi.
### Caratteristiche principali:

 	- **Motore**: elettrico da 160 kW (218 CV) con 350 Nm di coppia.
 	- **Batterie**: due opzioni disponibili, da 63 kWh o 76 kWh, per un’autonomia massima di circa 320 km.
 	- **Ricarica**: supporta fino a 350 kW in DC, permettendo di aggiungere 100 km di autonomia in meno di 10 minuti. Compatibile anche con AC fino a 11 kW.
 	- **Carico**: capacità di trasporto fino a 10 m³ e una portata utile di 1,5 tonnellate.
 	- **Interni**: equipaggiati con tecnologia avanzata, tra cui un sistema di infotainment da 10,25 pollici, sedili riscaldati e ventilati, e funzioni di sicurezza come il cruise control adattivo e il lane keeping assist.

 

![image](https://www.nolosubito.it/wp-content/uploads/2024/11/IVECO_eMoovy_my24_EStation_1126-300x200.jpeg) Con la ricarica più rapida nel suo segmento, fino a 350 kW, l''IVECO eMoovy raggiunge un''autonomia fino a 100 km in meno di 10 minuti, offrendoti una flessibilità senza pari.

![image](https://www.nolosubito.it/wp-content/uploads/2024/11/IVECO_eMoovy_my24_Int_2125-300x162.jpeg)Il quadro strumenti digitale configurabile TFT a colori da 12,3 pollici è posizionato sul cruscotto in modo da fornire al guidatore la migliore visibilità.
Il display LCD da 10,2 pollici del sistema di infotainment offre una navigazione chiara e intuitiva, semplificando la vita a bordo.

![image](https://www.nolosubito.it/wp-content/uploads/2024/11/IVECO_eMoovy_my24_FORWARD-COLLISION-AVOIDANCE-ASSIST_3-300x174.jpeg) Questa funzionalità ti fornirà informazioni su veicoli che sopraggiungono, così come i pedoni e i ciclisti sulla strada, emettendo un segnale acustico se questi sono troppo vicini e frenando automaticamente se necessario in modo da prevenire la collisione.

Questo veicolo segna un passo importante nella strategia di Iveco per la mobilità sostenibile, grazie all''uso di piattaforme e tecnologie Hyundai, combinando un approccio europeo con innovazioni globali. L’eMoovy punta a diventare un riferimento per la transizione energetica nel settore dei trasporti commerciali​

Per maggior informazioni potete richiedere un preventivo o informazioni --->  [https://www.iveco.com/italy/eMoovy](https://www.iveco.com/italy/eMoovy)',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/11/IVECO_eMoovy_my24_amb_people_1428-300x215.jpeg',
  true,
  '2024-11-28T12:24:55.000Z'::timestamptz
)
