  '**Audi e DS**

Ci siamo sempre promessi che per Natale ci saremmo fatti un regalo speciale... ed è arrivato il momento di mantenere quella promessa con la ***PROMOZIONE SANTACAR **e anche per i** NEOPATENTATI.***

Iniziamo con **AUDI Q3 SPORTBACK 35 TDI S tronic Business Plus **un SUV compatto che combina eleganza, sportività e versatilità. L’Audi Q3 Sportback 35 TDI S tronic è pensato per chi cerca comfort, tecnologia e prestazioni, senza rinunciare a uno stile distintivo. La versione Business Plus aggiunge un tocco premium, con dotazioni che esaltano l’esperienza di guida e il piacere di viaggiare.

![image](https://www.nolosubito.it/wp-content/uploads/2024/12/q3-sportback-2019-cover-300x300.jpeg)

 	- **Motore**: 2.0 TDI da 150 CV (110 kW)
