INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Il Santa Car dai regali inaspettati! Citroën C3 e C5 Aircross',
  'il-santa-car-dai-regali-inaspettati-citroen-c3-e-c5-aircross',
  'Citroën C3 e C5 Aircross La Citroën C3 Turbo 100 S&S Max iniziamo vol dire che può essere guidata anche dai Neopatentati , essa unisce il design iconico e moderno della C3 a prestazioni vivaci, garantendo un’esperienza di guida unica. Con il suo motore turbo, l’efficienza dei consumi e una dotazione',
  'Citroën C3 e C5 Aircross

![image](https://www.nolosubito.it/wp-content/uploads/2024/06/c3-1-300x300.png)

La **Citroën C3 Turbo 100 S&S Max** iniziamo vol dire che può essere guidata anche dai **Neopatentati**, essa unisce il design iconico e moderno della C3 a prestazioni vivaci, garantendo un’esperienza di guida unica. Con il suo motore turbo, l’efficienza dei consumi e una dotazione tecnologica all’avanguardia, è l’auto perfetta per affrontare sia la città che i lunghi viaggi. Lasciati conquistare dal comfort tipico di Citroën e dall''energia del motore turbo.

 	**Motorizzazione**:
Motore **PureTech Turbo 1.2** a benzina da **100 CV** con sistema Start&Stop (S&S), che ottimizza i consumi spegnendo il motore nelle soste.
 	- **Trasmissione**: Cambio manuale a 6 marce.
 	**Consumi**:
Ciclo combinato WLTP di circa **4,7-5,2 l/100 km**, con emissioni di CO₂ di circa **109-120 g/km**.
 	- **Prestazioni**: Velocità massima di **188 km/h** e accelerazione 0-100 km/h in circa **10 secondi**.
 	**Dimensioni**:

 	- Lunghezza: **3,99 m**
 	- Larghezza: **1,75 m**
 	- Altezza: **1,47 m**
 	- Capacità bagagliaio: **300 litri** (ampliabili abbattendo i sedili posteriori).

![image](https://www.nolosubito.it/wp-content/uploads/2017/09/citroen-c3-interno-300x225.jpg) può essere richiesta anche con il cambio automatico ma non per il motore da **100 CV.**

 	- La motorizzazione **PureTech Turbo 1.2 da 110 CV** può essere abbinata a un cambio automatico **EAT6** a 6 rapporti, che garantisce una guida fluida e confortevole, ideale per il traffico cittadino e i lunghi viaggi.

Gli esperti sottolineano l’agilità e il comfort della C3 Turbo 100 S&S Max, particolarmente adatta alla guida urbana ma anche capace di gestire con disinvoltura tratti autostradali. Il motore turbo offre una spinta energica e fluida, mentre le sospensioni garantiscono un assorbimento eccellente delle asperità stradali.

 

La **Citroën C3 Turbo 100 S&S Max **può essere tua a soli  **€ 217,00 + iva ------>  https://www.nolosubito.it/prodotto/citroen-c3/**

La **Citroën C5 Aircross BlueHDi 130 S&S Max EAT8** è un SUV versatile ed elegante, particolarmente apprezzato per il comfort, l''efficienza del motore diesel e il cambio automatico fluido.

![image](https://www.nolosubito.it/wp-content/uploads/2024/11/C5-NATALE-300x300.png)

Con il suo design robusto e distintivo, quindi, la **Citroën C5 Aircross BlueHDi 130 S&S Max EAT8** offre un’esperienza di guida unica. Equipaggiata con il motore diesel da 130 CV e il cambio automatico EAT8, questa versione è ideale per chi cerca comfort, efficienza e tecnologia in un SUV spazioso e pratico. Perfetta per i viaggi in famiglia o per affrontare la quotidianità con stile.

 	**Motorizzazione**:

 	- Motore **BlueHDi 1.5 turbodiesel** da **130 CV** (96 kW).
 	- Coppia massima: **300 Nm a 1.750 giri/min**.

 	**Cambio**:

 	- Cambio automatico **EAT8 a 8 rapporti**, progettato per cambi marcia fluidi e una guida rilassata.

 	**Consumi ed emissioni**:

 	- Ciclo combinato WLTP: **4,9-5,5 l/100 km**.
 	- Emissioni di CO₂: **130-145 g/km**.

 	**Prestazioni**:

 	- Velocità massima: **189 km/h**.
 	- Accelerazione 0-100 km/h: **10,4 secondi**.

 	**Dimensioni**:

 	- Lunghezza: **4,50 m**.
 	- Larghezza: **1,96 m**.
 	- Altezza: **1,67 m**.
 	- Capacità bagagliaio: **580 litri** (fino a **720 litri** spostando i sedili posteriori).

### **Dotazioni di serie**

 	**Comfort**:

 	- Sospensioni con **Progressive Hydraulic Cushions®**, che garantiscono un’ottima assorbenza delle asperità stradali.
 	- Sedili Advanced Comfort con imbottitura extra e regolazione lombare.

 	**Tecnologia**:

 	- Touchscreen da **10 pollici** con navigazione integrata e compatibilità con Apple CarPlay e Android Auto.
 	- Strumentazione digitale personalizzabile da **12,3 pollici**.

 	**Sicurezza**:

 	- Sistema di mantenimento della corsia.
 	- Cruise Control adattivo con funzione Stop & Go.
 	- Riconoscimento segnali stradali e frenata automatica d''emergenza.

I test evidenziano il **comfort eccezionale** del modello, grazie alle sospensioni avanzate e all’ergonomia dei sedili. Il motore BlueHDi 130 è silenzioso, efficiente e sufficientemente reattivo sia in città che in autostrada. Il cambio automatico EAT8 migliora ulteriormente la fluidità di guida.

![image](https://www.nolosubito.it/wp-content/uploads/2024/11/Citroen-C5-Aircross-BlueHDi-130-SS-Max-EAT8-300x300.png)

La **Citroën C5 Aircross BlueHDi 130 S&S Max EAT8 **può essere tua a soli** € 367,00 **+ iva  [https://www.nolosubito.it/prodotto/citroen-c5-aircross/](https://www.nolosubito.it/prodotto/citroen-c5-aircross/)',
