  '**Alfa Romeo Junior e Giulia**

**ALFA ROMEO JUNIOR 1.2 136CV Hybrid eDCT6 ibrida **è una vettura compatta ibrida che coniuga stile, prestazioni e sostenibilità, perfetta per chi cerca un''auto che si distingue per eleganza e innovazione tecnologica. Ecco le caratteristiche principali:

