**ALFA ROMEO GIULIA 2.2 TD 160cv Veloce AT8 **è una berlina premium che unisce prestazioni brillanti, design italiano e un''eccellente efficienza grazie al suo motore diesel. Ecco una panoramica delle sue caratteristiche:

