INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Patente di guida sul telefono? Ora si può',
  'patente-di-guida',
  'Patente di guida sul telefono? Ora si può. Dal 4 dicembre tutti i cittadini possono mettere patente, tessera sanitaria e e certificato di invalidità sullo smartphone. Nel 2025 altri documenti. Tutto all’interno dell’app IO, che diventa così wallet universale. Vediamo cosa significa di preciso e le i',
  'Patente di guida sul telefono? Ora si può.

Dal 4 dicembre tutti i cittadini possono mettere patente, tessera sanitaria e e certificato di invalidità sullo smartphone. Nel 2025 altri documenti. Tutto all’interno dell’app IO, che diventa così wallet universale. Vediamo cosa significa di preciso e le implicazioni.

La prima cosa da fare è da scaricare **App** " *Io* " e avere uno Spid attivo o una Carta d’Identità Elettronica .

Dopo di chè cliccare sulla sezione dedicata

![image](https://www.nolosubito.it/wp-content/uploads/2025/01/5e025a1d-fa2b-4f06-b77e-dcb8710ae7c1-135x300.png)

Una volta entrato nella selezione tramite Spid o una Carta d’Identità Elettronica, si può inserire i documenti richiesti o quali da voler inserire.

![image](https://www.nolosubito.it/wp-content/uploads/2025/01/patente_digitale_app-300x140.jpg)

Ovviamente non si tratta soltanto di una piccola grande rivoluzione tecnologica e pratica è anche una dimostrazione di visione e rapidità di esecuzione.

Ci sono, però, delle diciture da sapere:
- Il documento digitale non sostituisce quello di "plastica", che continuerà a essere rilasciato al conseguimento de alla conferma di validità.
- La patente mobile sarà del tutto equivalente alla card fisica, quindi può essere mostrata alle forze dell''ordine.
- Porta sempre con te la card fisica, qualora il cellulare fosse scarico è opportuno avere la card, altrimenti si va incontro a delle sanzioni.
- E'' valido solo in Italia.

Qui un breve video tutorial su come caricare i documenti sull''app... ---> [https://video.sky.it/news/tecnologia/video/come-attivare-la-patente-digitale-sullapp-io-960568](https://video.sky.it/news/tecnologia/video/come-attivare-la-patente-digitale-sullapp-io-960568)
Patente di guida',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/01/5e025a1d-fa2b-4f06-b77e-dcb8710ae7c1-135x300.png',
  true,
  '2025-01-07T14:56:34.000Z'::timestamptz
)
