INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Softcar - L''Auto Leggera che Cambia le Regole',
  'softcar-lauto-leggera',
  'Softcar l''auto leggera che cambia le regole. Sembra piccola, è invece... Questa volta il merito va alla Svizzera dove già nel 2019 iniziarono la progettazione. La nuova Softcar con i suoi 4 posti ma dalle dimensioni piccole ovvero lunga circa 3,2 mt e larga circa 1,6 mt potrebbe essere una concorren',
  '**Softcar l''auto leggera che cambia le regole.**

Sembra piccola, è invece... Questa volta il merito va alla Svizzera dove già nel 2019 iniziarono la progettazione.
La nuova Softcar con i suoi 4 posti ma dalle dimensioni piccole ovvero lunga circa 3,2 mt e larga circa 1,6 mt potrebbe essere una concorrente della Smart.
Progettata con alimentazione elettrica ma con un range extender a gas. La Softcar è un''innovativa city car ha legami con il vecchio progetto Swatchmobile, l''antenata della Smart. Progettata per essere leggera, sicura e con un ridotto impatto ambientale.
Essa è realizzata con una carrozzeria completamente riciclabile, composta da biopolimeri derivati da scarti alimentari.

Progettata in diversi colori e con porte ad ali di gabbiano.
![image](https://www.nolosubito.it/wp-content/uploads/2025/01/Softcar-300x140.png)

![image](https://www.nolosubito.it/wp-content/uploads/2025/01/softcar-quadriciclo-elettrico-smart-falcon-wing-v4-757172-1280x960-1-300x225.webp)

Il veicolo è modulare e può essere configurato in diverse versioni, tra cui trasporto merci, taxi, servizio postale o convertibile, offrendo così una grande versatilità d''uso. Con un''autonomia prevista di circa 200 chilometri, in versione elettrica mentre raddopia con il range extender a gas. Questo sistema consente di raggiungere una velocità massima compresa tra 135 e 140 km/h, rendendola adatta anche per l''utilizzo su autostrade.
La produzione della Softcar è prevista in micro-fabbriche con una capacità di 5.000 veicoli all''anno, un approccio che consente di ridurre gli investimenti iniziali e di localizzare la produzione vicino ai mercati di riferimento, favorendo l''economia locale e riducendo l''impronta di carbonio legata alla logistica.

Inoltre, la Softcar è membro dell''Alleanza Mondiale della Solar Impulse Foundation, che promuove soluzioni efficienti e sostenibili per l''ambiente. In sintesi, la Softcar rappresenta un passo avanti verso una mobilità urbana più sostenibile, combinando innovazione tecnologica, riduzione dell''impatto ambientale e accessibilità economica.

Qui il sito ufficiale ---> [https://www.softcar.com/en](https://www.softcar.com/en)
Video di presentazione ---> h[ttps://www.youtube.com/watch?v=1-Yokkqmz2g](https://www.youtube.com/watch?v=1-Yokkqmz2g)',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/01/Softcar-300x140.png',
  true,
  '2025-01-10T09:20:14.000Z'::timestamptz
)
