INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Vi presento la Fiat Giga Panda',
  'vi-presento-la-fiat-giga-panda',
  'Come sarà? «Il design sarà fortemente ispirato a quella originale del 1980. Squadrata, intelligente, pratica, sui 4 metri di lunghezza e con un prezzo accessibile: sarà una vera Panda. Sul nome ci stiamo ancora ragionando, potrebbe chiamarsi Panda Elettrica oppure chissà. La base su cui verrà costru',
  'Oggi vi voglio presentare la nuova Fiat Giga Panda.

Olivier François racconta la strategia che rivoluzionerà il marchio: «Lanceremo una nuova auto ogni anno fino al 2027. La prima sarà la nuova Panda». Ma chi è Olivier François? è un dirigente d''azienda francese, noto per il suo ruolo di leader nel settore automobilistico. È il Chief Marketing Officer (CMO) di **Stellantis**. Inoltre, François è anche il CEO del marchio **Fiat** e del marchio **Abarth**.

Già in un articolo precedente abbiamo presentato la Fiat Grande Panda ---> [https://www.nolosubito.it/curiosita/la-nuova-fiat-grande-panda/  ](https://www.nolosubito.it/curiosita/la-nuova-fiat-grande-panda/)che, molto probabilmente, la vettura sarà ordinabile da fine gennaio 2025 per poi arrivare entro un paio di settimane in concessionaria.

[caption id="attachment_2060277" align="alignnone" width="351"]![image](https://www.nolosubito.it/wp-content/uploads/2024/06/NUOVA-300x200.png) Grande Panda Fiat[/caption]

In un''intervista, Olivier François,  Pomigliano d’Arco (Napoli) - Un annuncio a sorpresa per cambiare il volto di Fiat: «Quattro nuovi modelli pronti al debutto da qui al 2027 tutti ispirati alla mitica Panda, quella squadrata e immortale».

***Come sarà?***
«Il design sarà fortemente ispirato a quella originale del 1980. Squadrata, intelligente, pratica, sui 4 metri di lunghezza e con un prezzo accessibile: sarà una vera Panda. Sul nome ci stiamo ancora ragionando, potrebbe chiamarsi Panda Elettrica oppure chissà. La base su cui verrà costruita (la piattaforma Smart Car, ndr) ci consente di proporla anche con motori ibridi per rispondere a tutte le esigenze dei diversi mercati».

![image](https://www.nolosubito.it/wp-content/uploads/2025/01/fiat-giga-panda1-300x200.png) ![image](https://www.nolosubito.it/wp-content/uploads/2025/01/fiat-giga-panda2-300x200.png)
La sua misura è di lunghezza 4.40 mt motore ancora ibrido full o elettrico. Segmento C a 7 posti. Dovremmo trovarla per le strade a fine luglio inizio agosto 2025 e sicuramente oltre alla vendita la si potrà anche noleggiare.

Qui un video di presentazione ---> [https://www.youtube.com/watch?v=4fvPIBBt1sk](https://www.youtube.com/watch?v=4fvPIBBt1sk)',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2024/06/NUOVA-300x200.png',
  true,
  '2025-01-27T10:11:32.000Z'::timestamptz
)
