INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'DS8 Il SUV Coupé di Lusso del Futuro',
  'ds8',
  'La DS N°8 è la nuova ammiraglia 100% elettrica di DS Automobiles, progettata per unire lusso, prestazioni elevate e comfort. Questo SUV-coupé di segmento D presenta dimensioni generose: 4,82 metri di lunghezza, 1,90 metri di larghezza, 1,58 metri di altezza e un passo di 2,90 metri. Il design aerodi',
  '**DS8 Il SUV Coupé di Lusso del Futuro**

DS N°8 è cosi che si chiamerà la nuova vettura elettrica, n° 8 come un profumo, in arrivo quest''estate 2025.
La DS N°8 è la nuova ammiraglia 100% elettrica di DS Automobiles, progettata per unire lusso, prestazioni elevate e comfort. Questo SUV-coupé di segmento D presenta dimensioni generose: 4,82 metri di lunghezza, 1,90 metri di larghezza, 1,58 metri di altezza e un passo di 2,90 metri. Il design aerodinamico, ispirato alla concept car DS Aero Sport Lounge, contribuisce a un coefficiente di resistenza aerodinamica (Cx) di appena 0,24.

Basata sulla piattaforma STLA Medium, la DS N°8 sarà prodotta nello stabilimento di Melfi, in Italia, con l''arrivo sulle strade previsto per la seconda metà del 2025. Il prezzo di partenza si aggirerà intorno ai 65.000 euro per la versione long range, che offre un''autonomia dichiarata di 750 km.

Gli interni della DS N°8 sono stati concepiti per offrire un''esperienza sensoriale unica, con materiali pregiati come la pelle Nappa con concia vegetale e dettagli ispirati al mondo della gioielleria. La tecnologia avanzata include il sistema DS IRIS SYSTEM con riconoscimento vocale potenziato da ChatGPT, un ampio schermo da 16'''' e funzioni di assistenza alla guida come DS DRIVE ASSIST 2.0 e DS NIGHT VISION.

350 Cavalli, velocità massima 190km/h , 750 chilometri di autonomia. 2 allestimenti Etoile e Pallas

![image](https://www.nolosubito.it/wp-content/uploads/2025/02/ds8_8-300x205.jpg) Versione Etoile  ![image](https://www.nolosubito.it/wp-content/uploads/2025/02/ds83-300x200.png)

Ricarica dal 20 al 80% e di 27 minuti con una colonnina da 160 kW.

![image](https://www.nolosubito.it/wp-content/uploads/2025/02/ds86-300x233.png) ![image](https://www.nolosubito.it/wp-content/uploads/2025/02/ds85-237x300.png) ![image](https://www.nolosubito.it/wp-content/uploads/2025/02/ds84-237x300.png)
Il responsabile dello stile della ds, Thierry Méetroz, è a lui che dobbiamo ringraziare per lo stile lussuoso ed elegante di tutte le DS. Tantissimi dettagli al suo interno a partire dal volante fino alle finiture in alluminio nel cruscotto.

Al momento sappiamo che uscirà quest''estate, ma non sappiamo la data esatta, ma sicuramente vi terremo aggiornati!

Qui tutti i dettagli ---> [https://www.dsautomobiles.it/modelli-ds/dsn8.html](https://www.dsautomobiles.it/modelli-ds/dsn8.html)',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/02/ds8_8-300x205.jpg',
  true,
  '2025-02-11T09:42:54.000Z'::timestamptz
)
