INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Scatola nera... scambio di informazioni',
  'scatola-nera-scambio-di-informazioni',
  'Scatola nera ... scambio di informazioni. È in vigore la legge che prevede lo scambio delle informazioni sulla buona condotta degli automobilisti tra le diverse compagnie assicurative, grazie alla scatola nera, ma sembra che ancora non si può applicare. Come tutte le cose pensate dal governo, sono n',
  '**Scatola nera ... scambio di informazioni.**

È in vigore la legge che prevede lo scambio delle informazioni sulla buona condotta degli automobilisti tra le diverse compagnie assicurative, grazie alla scatola nera, ma sembra che ancora non si può applicare.

Come tutte le cose pensate dal governo, sono non buone ma ottime, bisogna vedere però se si accetta la proposta e una volta portato sul campo bisogna vedere se verrà applicata.

A cosa serve la scatola nera?

 	La **geolocalizzazione**: permette di rintracciare il veicolo in caso di furto;
 	I **parametri di percorrenza**: statistiche basate su tempi di marcia e tempi di sosta con calcolo continuo in ore e minuti;
 	I **chilometri percorsi**: il numero di chilometri trascorso con analisi statistica delle distanze coperte in orari diurni e in orari notturni, il tipo di percorso usato (urbano, extraurbano, autostradale) con report di analisi percentuali per giorno, settimana, mese;
 	**Crash e impatti**: sono riportati data, accelerazione massima rilevata dal numero di giri motore, luogo risultante dalla localizzazione GPS, velocità al momento dell''impatto;
 	Dati sulla **guida del conducente**: il sistema monitora e registra l''uso del cambio, le marce
 	inserite e i giri del motore per potere analizzare nel dettaglio lo stile di guida;
 	L''**attivazione dei sistemi di sicurezza**: vengono inoltre registrati le eventuali attivazioni di dispositivi di sicurezza tra quelli in dotazione all''autovettura, tipo airbag e ABS.

*È obbligatorio? *
L''uso della scatola nera sulle **autovetture da strada**, in Italia, a differenza di quanto avviene in altri paesi in cui è obbligatoria da decenni, **è ad oggi ancora facoltativa**.

*Cosa invece prevede la legge?*
La buona condotta del conducente e a fine anno promuovere il conducente laddove si è comportato "bene", con sconti extra sull''assicurazione.
La buona condotta di guida include il rispetto delle regole, dei limiti di velocità e del Codice della Strada.',
  'Notizie',
  '',
  true,
  '2025-02-17T09:24:13.000Z'::timestamptz
)
ON CONFLICT (slug) DO UPDATE SET
