INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Documentazione per il noleggio',
  'documentazione-per-il-noleggio',
  'Documentazione per il noleggio Quanti noi nella nostra vita almeno una volta abbiamo noleggiato un auto? Ma quanti di noi realmente abbiamo letto le "regole"? In quest''articolo vi spiegheremo i punti principali dell''accordo quadro. Insieme alla documentazione del contratto c''è il famoso "Accordo Qua',
  'Documentazione per il noleggio

Quanti noi nella nostra vita almeno una volta abbiamo noleggiato un auto? Ma quanti di noi realmente abbiamo letto le "regole"?

In quest''articolo vi spiegheremo i punti principali dell''accordo quadro. Insieme alla documentazione del contratto c''è il famoso "Accordo Quadro" o " Condizioni Generali di Locazione" dove ci sono ben 33 punti sul noleggio.

Vediamo i punti principali:

**-** **Consegna del Veicolo:** La consegna del Veicolo da parte di LEASYS avverrà nel luogo concordato e indicato nella Richiesta RENT. Al ritiro, il Cliente, previa identificazione, firmerà il Verbale di Consegna, verificando la conformità e l’efficienza del veicolo.

**- Cancellazione dell’ordine: **Nei 14 giorni dalla data di sottoscrizione della Richiesta RENT, il Cliente avrà la facoltà di recedere dagli obblighi contrattuali previsti nella Richiesta RENT mediante comunicazione contenente dichiarazione esplicita della propria decisione di esercitare il diritto di recesso. Qualora il Cliente intendesse recedere decorsi 14 (quattordici) giorni dalla data di sottoscrizione della Richiesta RENT, LEASYS avrà la facoltà di richiedere al Cliente medesimo, a titolo di risarcimento per il danno procurato, un importo pari a sei canoni per ciascun Veicolo ordinato.

**- Modalità di utilizzo del Veicolo: **Il Cliente non può sublocare o cedere il Veicolo senza autorizzazione di LEASYS, che non risponde di infrazioni o modifiche non autorizzate. Le revisioni periodiche sono obbligatorie; se incluse, le spese spettano a LEASYS, ma le sanzioni restano a carico del Cliente.

**- Chi può guidare l''auto?**
Ove il Cliente sia qualificabile come persona *giuridica* potrà, sotto la sua responsabilità, concedere in uso il Veicolo a persone che siano dipendenti e/o facenti parte dell’organizzazione societaria del Cliente medesimo. Ove il Cliente si a qualificabile come persona fisica il Cliente potrà concedere in uso il Veicolo ai propri familiari purché conviventi.

**- Durata della locazione:**La Locazione decorre dalla data del Verbale di Consegna e comunque entro 5 giorni dalla comunicazione di disponibilità. Trascorsi 5 giorni, LEASYS avvierà la fatturazione, anche senza ritiro del Veicolo.

**- Percorrenza chilometrica: **Qualora, durante la Locazione, il Cliente rilevasse proiezioni di percorrenze chilometriche superiori a quelle indicate nella Richiesta RENT, dovrà darne tempestiva comunicazione a LEASYS ai fini dell''adeguamento del canone di Locazione in funzione della nuova percorrenza chilometrica massima. Tale adeguamento del canone di Locazione, potrà avvenire mediante una pattuita modifica contrattuale.

**- Manutenzione e/o riparazione: **Se previsto, LEASYS garantirà la manutenzione tramite fornitori convenzionati. Il Cliente può effettuare interventi solo con autorizzazione. Le strutture autorizzate sono consultabili sul sito di LEASYS.

Questi sono 7 dei punti principali dell'' accordo, ma se avete altre domande non esitate a contattarci sul noleggio e le sue regole.',
  'Notizie',
  '',
  true,
  '2025-02-25T10:31:22.000Z'::timestamptz
)
