INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Tesla ritira Model Y e Model 3',
  'tesla-ritira-model-y-e-model-3',
  'Il guasto potrebbe provocare un surriscaldamento del motore del servosterzo, compromettendone parzialmente o totalmente la funzionalità. Secondo Tesla, tuttavia, il problema si verifica esclusivamente quando il veicolo è fermo o procede a bassa velocità. Fortunatamente, non sono stati segnalati inci',
  'Tesla ritira Model Y e Model 3

Un altro richiamo per la casa Tesla, dopo quella di Gennaio dove era legato a un malfunzionamento della telecamera Model S e Model X. Questa volta centra 2 modelli Model Y e Model 3.
La causa è proprio il servosterzo, che a causa di alcune anomalie può richiedere eccessivo sforzo nelle manovre, specie quelle a bassa velocità.
Il guasto potrebbe provocare un surriscaldamento del motore del servosterzo, compromettendone parzialmente o totalmente la funzionalità. Secondo Tesla, tuttavia, il problema si verifica esclusivamente quando il veicolo è fermo o procede a bassa velocità.
Fortunatamente, non sono stati segnalati incidenti legati a questo difetto. La stessa Tesla ha rassicurato i clienti, affermando che, fino a oggi, non si sono verificati episodi gravi o fatali riconducibili a questa anomalia.
Il problema è emerso in seguito a oltre 3.000 richieste di intervento in garanzia relative a determinate Model Y e Model 3 dotate di una versione precedente del sistema di assistenza alla guida. Di conseguenza, i modelli più recenti, come il Model Y 2025, non rientrano nel richiamo.
In circa 50 episodi, i proprietari hanno dovuto ricorrere a un carro attrezzi, poiché la sterzata era diventata impossibile c’è chi dichiara addirittura di non riuscire a sterzare, mentre altri denunciano sforzi eccessivi nelle manovre. . Tesla prevede di inviare comunicazioni scritte ai 380.000 clienti interessati entro il 27 marzo. Nel frattempo, invita i proprietari a monitorare eventuali anomalie e a contattare l’assistenza se necessario. La Tesla ha affermato che alcune Model 3 e Model Y potrebbero avere questo genere di problemi perché dotate di un software obsoleto. La Casa ha disposto un aggiornamento over-the-air per risolvere il guasto.

Anche i migliori possono sbagliare ;)

** **',
  'Notizie',
  '',
  true,
  '2025-02-26T10:22:17.000Z'::timestamptz
)
