INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Roma, 17 auto Tesla bruciate',
  'roma-17-auto-tesla-bruciate-incendio',
  'Tesla Incendio - Roma, 17 auto Tesla bruciate Il 31 Marzo intorno alle 4:30, a Roma nella casa Tesla è scoppiato un incendio, dove sono state distrutte 17 auto elettriche Tesla, per fortuna non ci sono danni a persone. In giorno stesso dell''accaduto non si sapeva ancora se l''incendio fosse voluto o ',
  '**Tesla Incendio - Roma, 17 auto Tesla bruciate**

Il 31 Marzo intorno alle 4:30, a Roma nella casa Tesla è scoppiato un incendio, dove sono state distrutte 17 auto elettriche Tesla, per fortuna non ci sono danni a persone.
In giorno stesso dell''accaduto non si sapeva ancora se l''incendio fosse voluto o meno, ma ad oggi possiamo dire che è stato un attentato. Non è stato un attacco isolato: poche ore prima bruciava una piazzola di ricariche in Francia, a Saint Chamond, e il 29 marzo il movimento globale Tesla Takedown che sul web invita al boicottaggio ha contato azioni in 250 città in tutto il mondo contro le auto simbolo dell’impero di Elon Musk.

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/Schermata-2025-04-07-alle-09.35.57-300x281.png)

Tesla Center è completamente intatto e regolarmente aperto. Le fiamme hanno invece colpito alcune auto in attesa di consegna ai clienti, parcheggiate in un’area adiacente.

A marzo si sono registrati episodi simili sia in Europa che America. A Tolosa, in Francia, hanno preso fuoco 8 auto a inizio mese, mentre a Ottersberg (Germania) un rogo ha riguardato altri 7 veicoli solo nei giorni scorsi.

Oltreoceano, sempre a marzo, è stata colpita ad Austin (Texas), dove sono stati trovati dispositivi incendiari in una concessionaria che hanno portato all’intervento di polizia e artificieri, e a Las Vegas (Nevada), dove un uomo è stato arrestato con l’accusa di incendio e vandalismo su veicoli e un centro assistenza.

Quindi sarà stato un incendio doloso oppure no?

 

Qui link --- >[https://x.com/ultimoranet/status/1906618380859097139](https://x.com/ultimoranet/status/1906618380859097139)',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/04/Schermata-2025-04-07-alle-09.35.57-300x281.png',
  true,
  '2025-04-07T08:39:40.000Z'::timestamptz
)
