INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Smart #5 Brabus la più potente',
  'smart-5-brabus-la-piu-potente',
  'La Smart #5 Brabus è equipaggiata con una batteria da 100 kWh (94 kWh utilizzabili), che, secondo i dati forniti dal costruttore, garantisce un’autonomia fino a 540 km con una singola carica. Grazie all’architettura elettrica a 800 volt, supporta una potenza di ricarica fino a 400 kW in corrente con',
  '**Smart #5 Brabus è la più potente**

La Smart #5 Brabus rappresenta la declinazione più sportiva della nuova SUV elettrica #5, che misura 470 cm in lunghezza ed è da poco disponibile per l’ordinazione. Come le sorelle minori #1 e #3, anche questo modello nasce dalla joint venture tra il gruppo cinese Geely e Mercedes-Benz. Con i suoi due motori elettrici – uno per ciascun asse – la #5 Brabus offre trazione integrale e una potenza complessiva di ben 646 CV, rendendola la Smart più potente mai realizzata. Secondo i dati ufficiali, accelera da 0 a 100 km/h in appena 3,8 secondi e può raggiungere una velocità massima di 210 km/h.

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/large_hashtag5-brabus-atomic-grey-matte-still-interior-wide-oled-screens-srgb-300x200.jpeg) ![image](https://www.nolosubito.it/wp-content/uploads/2025/04/large_smart-hashtag5-brabus-eu-10-300x200.jpeg)
La Smart #5 Brabus è equipaggiata con una batteria da 100 kWh (94 kWh utilizzabili), che, secondo i dati forniti dal costruttore, garantisce un’autonomia fino a 540 km con una singola carica. Grazie all’architettura elettrica a 800 volt, supporta una potenza di ricarica fino a 400 kW in corrente continua: in condizioni ideali e con una colonnina compatibile (ancora rare), il passaggio dal 10 all’80% della carica avviene in soli 18 minuti. In corrente alternata, invece, l’auto può essere ricaricata a 22 kW, richiedendo circa sei ore per una ricarica completa.

Rispetto alla versione standard della Smart #5, la variante Brabus si distingue per elementi estetici e tecnici specifici: cerchi in lega da 21 pollici e dettagli rossi che spiccano sui paraurti, sugli specchietti e sul tetto. L’abitacolo riflette la stessa sportività, con sedili in microfibra dotati di ventilazione e riscaldamento, cuciture rosse a contrasto e cinture abbinate. Il volante, in Alcantara, integra il logo Brabus retroilluminato nella razza inferiore. A bordo spiccano tre display: un quadro strumenti da 10,2 pollici e due schermi OLED da 13 pollici, uno centrale e uno dedicato al passeggero, entrambi con un’eccellente qualità visiva. L’impianto audio, firmato Sennheiser, sviluppa ben 1.190 Watt attraverso 20 altoparlanti.

Con un passo generoso di 290 cm, l’abitabilità interna è notevole, soprattutto nella zona posteriore, dove anche tre adulti di corporatura robusta possono viaggiare comodamente. Il bagagliaio, accessibile tramite un portellone elettrico, offre una capacità di 630 litri, espandibile fino a 1.530 litri abbattendo i sedili posteriori. La Smart #5 Brabus sarà ordinabile in Italia dal 17 giugno 2025 a un prezzo di 63.294 euro. Le versioni con potenze inferiori partiranno da 47.935 euro.

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/large_smart-hashtag5-brabus-eu-2-300x200.jpeg)',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/04/large_hashtag5-brabus-atomic-grey-matte-still-interior-wide-oled-screens-srgb-300x200.jpeg',
  true,
  '2025-04-10T09:52:17.000Z'::timestamptz
)
