INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Papa Francesco e le sue auto',
  'papa-francesco-e-le-sue-auto',
  'Papa Francesco, nato Jorge Mario Bergoglio, è stato eletto Sommo Pontefice il 13 marzo 2013, succedendo a Benedetto XVI. Il suo pontificato si è concluso il 21 aprile 2025, durando complessivamente 12 anni .',
  '**Papa Francesco e le sue auto.**

Papa Francesco:purtroppo la brutta notizia ha fatto il giro del mondo. Vediamo insieme, nel corso degli anni, quali auto lo hanno accompagnato.
Papa Francesco, nato Jorge Mario Bergoglio, è stato eletto Sommo Pontefice il 13 marzo 2013, succedendo a Benedetto XVI. Il suo pontificato si è concluso il 21 aprile 2025, durando complessivamente 12 anni.

Durante questi dodici anni, Papa Francesco ha guidato la Chiesa cattolica con uno stile pastorale improntato alla semplicità, alla vicinanza ai poveri e all''attenzione per le periferie esistenziali, non solo, ma è stato anche il primo Pontefice ad aver mostrato sensibilità verso l''ambiente e la sostenibilità, in che modo? Con le auto per esempio.

Iniziamo con nel dicembre 2024 dove,  Papa Francesco ha ricevuto la **prima** papamobile completamente elettrica: una Mercedes Classe G 580 EQ. Questo veicolo, realizzato su misura per le uscite pubbliche è dotato di quattro motori elettrici, una potenza complessiva di 432 kW e un''autonomia di circa 470 km.

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/2-300x169.jpeg)

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/3-300x169.jpeg)

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/4-300x169.jpeg)

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/mercedes-classe-g-papamobile-2024-300x169.jpeg)
La papamobile presenta una cupola in vetro removibile che è risultata ideale per le **apparizioni pubbliche** in Piazza San Pietro; **anche nell''ultima**, della Domenica di Pasqua, prima della sua scomparsa.

L’interesse di Papa Francesco per le auto a zero emissioni non è recente. Già durante il viaggio in Giappone, nel novembre 2020, aveva utilizzato una Toyota Mirai appositamente modificata per i suoi spostamenti.Quella stessa vettura, successivamente, fu donata al Pontefice dalla Conferenza Episcopale Giapponese e arrivò ufficialmente in Vaticano nel 2021. Sebbene mai dichiarata papamobile ufficiale, è considerata la prima vettura papale alimentata a idrogeno della storia.

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/2°-300x169.jpeg)

In qualità di Capo di Stato Papa Francesco ha provveduto anche a elettrificare la mobilità nella Città del Vaticano, con due smart ForFour EQ concesse da Mercedes-Benz in Comodato d’uso proprio al Governatorato Vaticano. ![image](https://www.nolosubito.it/wp-content/uploads/2025/04/anche-il-vaticano-sceglie-le-zero-emissioni-300x169.jpeg)

Anche con la 500L ha viaggiato.
![image](https://www.nolosubito.it/wp-content/uploads/2025/04/cq5dam.thumbnail.cropped.1500.844-300x198.jpeg)

Nel 2017 Lamborghini donò a Papa Francesco una Huracan unica, bianca con strisce gialle vaticane. L’auto, firmata dal Pontefice, fu venduta all’asta nel 2018 per 715 mila euro, poi devoluti in beneficenzaStessa sorte per la **Harley-Davidson Dyna Super Glide Custom** donata a Bergoglio nel 2014, diventata un assegno da **250 mila euro** per la Caritas.

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/67bdda9793e47-300x200.jpeg)

Infine la sua amata  **Renault 4**. Francesco era legato a questo modello che utilizzava in Argentina, inizialmente da sacerdote e poi da arcivescovo di Buenos Aires. i.

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/67bac60fee311.r_d.599-413-0-300x147.jpeg)
Insomma questo Papa ha pensato proprio a tutto e a tutti, rimarrà nei nostri cuori per sempre.',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/04/2-300x169.jpeg',
  true,
  '2025-04-23T10:19:11.000Z'::timestamptz
)
