INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Nuova casa negli USA - SLATE',
  'nuova-casa-negli-usa-slate',
  'Infotainment e la connettività : Non sono presenti. Video. https://www.youtube.com/watch?v=jKVwEg4ZToI',
  'Nuova casa negli USA - SLATE

L''essenziale, è questa la parola chiave del momento. **Slate Auto** è una startup americana nel settore dei veicoli elettrici (EV), fondata nel 2022 e con sede a Troy, Michigan. Sostenuta da Jeff Bezos e altri investitori di alto profilo, l''azienda mira a rivoluzionare il mercato dei veicoli elettrici con un approccio incentrato su semplicità, accessibilità economica e personalizzazione.

Il primo modello è stato presentato da pochissimi giorni il 24 aprile 2025, lo Slate Truck è un pick-up elettrico compatto a due posti, progettato per essere estremamente personalizzabile. Il prezzo base è di circa $27.500, ma grazie agli incentivi federali per i veicoli elettrici, il costo effettivo per il consumatore potrebbe scendere sotto i $20.000, rendendolo uno dei veicoli elettrici più economici sul mercato statunitense. ​

 

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/SlateMain-300x169.webp)
Le sue caratteristiche - Motore: Singolo motore posteriore da 201 CV (150 kW) con trazione posteriore. Batteria: Disponibile in due versioni: 52,7 kWh per un''autonomia di circa 240 km e 84,3 kWh per circa 385 km. Caricamento: Supporta la ricarica AC fino a 11 kW e DC fino a 120 kW tramite connettore NACS. Dimensioni: Lunghezza di 4,45 metri, larghezza di 1,79 metri e altezza di 1,76 metri. Capacità di carico: Fino a 650 kg di carico utile e 450 kg di capacità di traino. ​

**L''essenziale**, manca praticamente tutto, a parte un volante e una coppia di sedili, non c’è la radio, né gli altoparlanti, né tanto meno uno schermo per il sistema multimediale (al centro della plancia c’è un supporto per lo smartphone). Non ci sono nemmeno i finestrini elettrici.

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/slate-pick-up-2025-04_08-300x169.jpeg)
Ma ovviamente offrire massima libertà di personalizzazione. Questa è la versione base.
Infotainment e la connettività  : Non sono presenti.

![image](https://www.nolosubito.it/wp-content/uploads/2025/04/slate-truck-front-3-4-exterior-300x169.jpeg)

Video.
[https://www.youtube.com/watch?v=jKVwEg4ZToI](https://www.youtube.com/watch?v=jKVwEg4ZToI)',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/04/SlateMain-300x169.webp',
  true,
  '2025-04-29T10:59:19.000Z'::timestamptz
)
