INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Nuova Skoda Elroq',
  'nuova-skoda-elroq',
  'Elroq 50 : motore da 170 CV, batteria da 52 kWh, autonomia fino a 375 km.',
  '**Nuova Skoda Elroq**

La Škoda Elroq è un SUV compatto completamente elettrico, progettato per offrire un equilibrio tra sostenibilità, tecnologia e praticità. Funzionale e concreta, la nuova Skoda Elroq convince tutti - 100% elettrica.
La Elroq è disponibile in diverse versioni, tutte con trazione posteriore:

 	
Elroq 50: motore da 170 CV, batteria da 52 kWh, autonomia fino a 375 km.

 	
Elroq 60: motore da 204 CV, batteria da 59 kWh, autonomia fino a 429 km.

 	
Elroq 85: motore da 286 CV, batteria da 77 kWh, autonomia fino a 580 km.

 	
Elroq 85x: trazione integrale con potenza combinata di 299 CV, disponibile dal 2025.

La Elroq adotta il nuovo design "Modern Solid" di Škoda, con linee minimaliste e robuste. Il frontale è dominato da una calandra chiusa e fari a LED sottili, mentre il posteriore presenta gruppi ottici orizzontali e il nome Škoda scritto a lettere.
L''abitacolo della Elroq segue il nuovo linguaggio di design "Modern Solid", caratterizzato da linee pulite e materiali sostenibili. Tra le dotazioni spiccano:

 	
Digital Cockpit da 5 pollici.

 	
Head-up display con realtà aumentata.

 	
Sistema infotainment con touchscreen da 13 pollici con interfaccia Android e Apple wireless + assistente vocale con ChatGpt.

 	
Ampio bagagliaio da 470 litri, espandibile a 1.580 litri abbattendo i sedili posteriori.

![image](https://www.nolosubito.it/wp-content/uploads/2025/05/Skoda-Elroq-1-300x171.webp). ![image](https://www.nolosubito.it/wp-content/uploads/2025/05/interni-skoda-elroq-2024-300x167.webp) ![image](https://www.nolosubito.it/wp-content/uploads/2025/05/20250520_150618-300x195.png)
Volante riscaldabile, sotto al voltante un spazio per posizionare un piccolo ombrello.

 

![image](https://www.nolosubito.it/wp-content/uploads/2025/05/Default_bp1200_1-300x150.webp) ![image](https://www.nolosubito.it/wp-content/uploads/2025/05/Default_bp1200_1-1-300x150.webp)

