INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'La prima auto fu la Suzulight',
  'la-prima-auto-fu-la-suzulight',
  'La prima versione della Suzulight si presenta con una carrozzeria a due porte e tre volumi, equipaggiata con un motore a due tempi di derivazione motociclistica montato anteriormente, abbinato alla trazione anteriore — una scelta tecnica all’avanguardia per l’epoca.',
  'Sì, è proprio così! La Suzulight, nata nell’ottobre 1955, fu la prima automobile costruita da Suzuki. Fino ad allora la casa giapponese produceva solo telai e motociclette. La Suzulight inaugurò il successo di Suzuki nel settore automobilistico 70 anni fa, presentando fin dall’inizio soluzioni all’avanguardia come la trazione anteriore, sospensioni a molle elicoidali indipendenti e sterzo a cremagliera.

Ci siamo sempre chiesti quale fosse, ed eccola qui

![image](https://www.nolosubito.it/wp-content/uploads/2025/07/SUZUKI3-1-300x200.png)

Dopo i buoni successi con la produzione motociclistica, la Suzuki decide di cimentarsi anche nel campo automobilistico. È l''ottobre 1955 quando viene presentata la **Suzulight SS**, una vetturetta progettata ispirandosi alla tecnologia tedesca del dopoguerra, in particolare al modello Lloyd LP 300. Fa parte del gruppo di vetture definite Keycar, agevolate in Giappone sotto il profilo fiscale.
La Suzulight è un pezzo di storia automobilistica giapponese: non solo fu la prima auto prodotta da Suzuki, ma anche un veicolo pionieristico per il Giappone del dopoguerra.

![image](https://www.nolosubito.it/wp-content/uploads/2025/07/SUZUKI2-300x213.png)
La prima versione della Suzulight si presenta con una carrozzeria a due porte e tre volumi, equipaggiata con un motore a due tempi di derivazione motociclistica montato anteriormente, abbinato alla trazione anteriore — una scelta tecnica all’avanguardia per l’epoca.

Grazie al prezzo accessibile, ai bassi costi di gestione e alla buona abitabilità per quattro passeggeri (in linea con la statura media giapponese di quegli anni), l’auto conquista rapidamente il mercato, diventando un successo commerciale fin dal debutto.

La Suzulight si trasforma presto in un’icona della rinascita economica del Giappone del dopoguerra: apprezzata sia dalle famiglie più agiate, che la utilizzano come seconda auto, sia da quelle meno abbienti, che per la prima volta possono permettersi un veicolo privato.

Per soddisfare le diverse esigenze della clientela, Suzuki sviluppa numerose varianti di carrozzeria. Tra queste riscuotono particolare successo la versione SD, una familiare compatta a tre porte e quattro posti, e la versione SP, un pick-up a due posti pensato per il lavoro.

Nel 1958, i tecnici Suzuki introducono importanti aggiornamenti: il passo aumenta da 2.000 a 2.050 mm e la potenza passa da 16 a 21 cavalli.

Nel 1959 debutta la versione Van, un furgoncino a tre porte con passo di 1.870 mm e sospensioni posteriori a balestra, progettato per il trasporto leggero.

L’ultima evoluzione della gamma è rappresentata dalla Suzulight Fronte, prodotta tra il 1962 e il 1965. Questo modello segna il passaggio alla nuova serie “Fronte”, che prenderà il posto della Suzulight nella gamma utilitaria di Suzuki durante gli anni Sessanta e Settanta.',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/07/SUZUKI3-1-300x200.png',
  true,
  '2025-07-07T08:06:47.000Z'::timestamptz
)
ON CONFLICT (slug) DO UPDATE SET
  title          = EXCLUDED.title,
  summary        = EXCLUDED.summary,
  content        = EXCLUDED.content,
  category       = EXCLUDED.category,
  cover_image_url = EXCLUDED.cover_image_url,
  is_published   = EXCLUDED.is_published,
  published_date = EXCLUDED.published_date;

INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Vi presentiamo la nuova Mercedes CLA',
  'vi-presentiamo-la-nuova-mercedes-cla',
  'Mercedes GLC 2025: la svolta elettrica debutta a Monaco',
  '**Mercedes CLA Shooting Brake 2026**

Come abbiamo già anticipato, la nuova Mercedes CLA qui vi mostreremo un breve video ma il SUV debutterà al Salone di Monaco 2025 (dal 9 al 14 Settembre).
Mercedes GLC 2025: la svolta elettrica debutta a Monaco

La rivoluzione della Mercedes GLC è ormai alle porte: il debutto ufficiale avverrà il 7 settembre al Salone di Monaco 2025. La grande novità? Sarà completamente elettrica. Un passaggio storico per il SUV più venduto della Stella, che in un video teaser pubblicato da Mercedes viene svelato durante una sessione di test, guidato direttamente dal CEO Ola Källenius.

Nel filmato, la nuova GLC affronta un percorso slalom, mettendo in mostra l’efficacia delle sospensioni pneumatiche Airmatic, ereditate dalla Classe S. Chi desidera il massimo in termini di dinamica potrà optare per il pacchetto opzionale Agility & Comfort, che include anche le quattro ruote sterzanti per una maggiore agilità in manovra.

Primi dettagli pratici: spazio, frunk e autonomia

Durante un''altra fase del test, l''attenzione si sposta sul bagagliaio. La silhouette da coupé riduce leggermente l''altezza utile del vano posteriore, mentre si nota un piccolo scalino all''ingresso. Dopo aver caricato il baule, Källenius ripone una borsa nel vano anteriore: la GLC offre infatti anche un frunk da 128 litri. Il bagagliaio principale ha una capacità compresa tra 570 e 1.740 litri.

La parte forse più attesa riguarda la ricarica: la GLC promette di recuperare 280 km di autonomia in appena 10 minuti, grazie a una potenza di picco di 320 kW. L’autonomia complessiva dichiarata tocca i 650 km.

Anche trainare non sarà un problema

Nel finale del video, la nuova GLC dimostra di non temere i carichi pesanti. Il SUV elettrico traina con disinvoltura un carrello con sopra una storica 300 SEL. Mercedes comunica che la capacità di traino raggiunge i 2.400 kg.

![image](https://www.nolosubito.it/wp-content/uploads/2025/07/2026-mercedes-benz-glc-ev-300x169.jpeg) ![image](https://www.nolosubito.it/wp-content/uploads/2025/07/2026-mercedes-benz-glc-ev-prototype-in-car-driving-300x169.jpeg)![image](https://www.nolosubito.it/wp-content/uploads/2025/07/2026-mercedes-benz-glc-ev-300x169.jpeg) ![image](https://www.nolosubito.it/wp-content/uploads/2025/07/2026-mercedes-benz-glc-ev-prototype-in-car-driving-300x169.jpeg)

Design e tecnologia: cosa aspettarsi

A livello estetico, spiccano le nuove firme luminose a LED, anteriori e posteriori, con l’inconfondibile motivo a stella già visto sulla CLA di nuova generazione. Gli interni non sono ancora stati svelati, ma la Casa promette un avanzato sistema MBUX Hyperscreen completamente rinnovato.

Cambia anche la base tecnica: la nuova GLC cresce nel passo di 8 cm, raggiungendo circa 2,96 metri, il che lascia presagire maggior comfort a bordo.

Mercedes CLA Shooting Brake 2025: la prima station wagon elettrica della Stella

Parallelamente, Mercedes presenta anche un’altra novità strategica: la CLA Shooting Brake 2025. È la prima wagon full electric del marchio, realizzata su una piattaforma completamente nuova pensata per ospitare sia propulsori elettrici (architettura a 800V) sia motorizzazioni mild-hybrid benzina, in arrivo nel 2026.

L’abbiamo potuta osservare dal vivo a Copenaghen: materiali raffinati, ottima cura dei dettagli e un’abitabilità migliorata grazie al passo aumentato (ora a 2,79 metri). La vettura è lunga poco più di 4,70 m, larga 1,85 m e alta 1,47 m. Le forme filanti, con tetto discendente e maniglie a filo carrozzeria, migliorano l’aerodinamica e aggiungono eleganza.

Il posteriore, più muscoloso rispetto alla berlina, si distingue per uno spoiler ben integrato e una striscia LED posteriore frammentata in piccoli punti luce. Anche il frontale adotta la firma luminosa a stella, per un family feeling coerente con la nuova direzione stilistica del marchio.

[https://www.youtube.com/watch?v=34zBLhrEtu0 ](https://www.youtube.com/watch?v=34zBLhrEtu0)',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/07/2026-mercedes-benz-glc-ev-300x169.jpeg',
  true,
  '2025-07-15T08:30:07.000Z'::timestamptz
)
