INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Nuova Ferrari Elettrica',
  'nuova-ferrari-elettrica',
  'Ferrari mantiene ancora il massimo riserbo sul design e sulle specifiche tecniche, ma alcune informazioni sono già trapelate:',
  'Ferrari Elettrica

La rivoluzione elettrica arriva anche a Maranello. Dopo mesi di indiscrezioni, Ferrari ha fissato la data: il 9 ottobre 2025 sarà presentata ufficialmente la sua prima supercar 100% elettrica, un evento epocale per la Casa del Cavallino Rampante. Le prime consegne sono previste per ottobre 2026, aprendo un nuovo capitolo nella storia del marchio.
**Caratteristiche attese**

Ferrari mantiene ancora il massimo riserbo sul design e sulle specifiche tecniche, ma alcune informazioni sono già trapelate:

 	
Potenza: si parla di oltre 1.000 CV, per mantenere intatto il DNA delle Rosse.

 	
Batterie: pacco sviluppato in collaborazione con fornitori europei, con tecnologia ad alta densità energetica.

 	
Autonomia: stimata intorno ai 500 km WLTP, pur privilegiando le prestazioni rispetto alla percorrenza.

 	
Prestazioni: accelerazione 0-100 km/h in meno di 3 secondi e velocità massima superiore ai 300 km/h.

 	
Sound artificiale: Ferrari avrebbe studiato un sistema acustico dedicato per garantire un’esperienza emozionale simile al rombo termico.

Per la nuova elettrica, Ferrari ha costruito un nuovo polo produttivo a Maranello, chiamato E-Building, dove nasceranno i modelli a batteria, ibridi e futuri motori a basse emissioni. Una scelta che testimonia la volontà di integrare l’elettrico senza tradire le radici artigianali del marchio.

 

La prima Ferrari elettrica non sarà una semplice sportiva a batteria, ma un manifesto tecnologico. Maranello vuole dimostrare che anche senza V8 o V12 un’auto può offrire prestazioni estreme ed emozioni uniche. L’appuntamento è fissato: ottobre 2025 segnerà l’inizio di una nuova era.

E voi cosa ne pensate??
##',
  'Notizie',
  '',
  true,
  '2025-09-24T09:34:06.000Z'::timestamptz
)
