INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Nuova Smart #2',
  'nuova-smart-2',
  'Il CEO Dirk Adelmann ha affrontato la domanda che tutti si pongono: come sarà davvero il ritorno, atteso per il 2026, della storica due posti? «Stiamo chiedendo ai nostri ingegneri il massimo», spiega, «per trovare il punto di equilibrio ideale tra costo delle batterie ed equipaggiamenti. L’obiettiv',
  'Dimentichiamoci della vecchia Smart a 2 posti, nel 2027 uscirà la nuova sempre a 2 posti ma solo in versione elettrica.

Il motto per la casa è È sempre fortwo. Solo più smart: #2
Il CEO Dirk Adelmann ha affrontato la domanda che tutti si pongono: come sarà davvero il ritorno, atteso per il 2026, della storica due posti? «Stiamo chiedendo ai nostri ingegneri il massimo», spiega, «per trovare il punto di equilibrio ideale tra costo delle batterie ed equipaggiamenti. L’obiettivo è creare un’auto pensata per un pubblico ampio, non un prodotto di nicchia».

Al di là dell’entusiasmo per il suo ritorno, ciò che interessa davvero è il prezzo. In 26 anni di carriera — interrotta solo nel 2024 — la fortwo ha conquistato il mercato italiano con 650.000 unità vendute, attraversando tre generazioni e passando da 250 a 270 centimetri di lunghezza. Oggi si parla molto di piccole elettriche europee e soluzioni di mobilità alternative ai quadricicli, ma la fortwo aveva già anticipato questo trend, diventando completamente elettrica nel 2019. Quella scelta, tuttavia, aveva mostrato limiti evidenti sull’autonomia.

Ora, con il suo ritorno ufficializzato e un’anteprima che ne suggerisce forme e nome definitivo — smart #2 — resta da capire quale sarà la fascia di prezzo. Solo Adelmann può dare qualche indicazione.

Si potrà davvero avvicinare ai 20.000 euro?«È presto per parlare di cifre precise», chiarisce. «Ma alcuni elementi li possiamo già condividere. Vogliamo comunicare un messaggio forte: l’icona sta tornando. E deve essere accessibile, pratica, desiderabile. Prendiamo come riferimento l’ultima generazione della fortwo, anche se oggi gli standard di sicurezza e omologazione sono più severi. E non avremmo mai potuto proporre un’elettrica con appena 130 km di autonomia. I nostri ingegneri stanno lavorando per ridurre ogni costo superfluo, controllando ogni dettaglio con un’attenzione quasi maniacale. Sarà certamente più economica della smart #1, che parte da 37.000 euro. Potrebbe però arrivare anche una versione sportiva, destinata a un prezzo più alto. Ora è tutto nelle mani del nostro team tecnico, sotto pressione come mai prima d’ora per ottimizzare dotazioni e tecnologia senza perdere di vista l’obiettivo finale».

Da quasi tre decenni, smart ha ridisegnato l’idea stessa di mobilità cittadina: piccola, scattante, unica nel suo genere. Oggi questo simbolo si rinnova, cambia nome e guarda avanti: nasce smart #2.

Una nuova interpretazione della city car: compatta come sempre, più sicura, più tecnologica, completamente elettrica. Due posti, nessun compromesso, 100% spirito urbano.

Grazie all’Editoriale Quattroruote probabilmente la smart #2 sarà cosi

![image](https://www.nolosubito.it/wp-content/uploads/2025/12/SMART2-1-300x200.png)

La trazione dovrebbe rimanere sul retro, come da tradizione. Potenza intorno ai 100 cavalli e un range di 200-250km, posti x 2 con lunghezza sui 2,70mt',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2025/12/SMART2-1-300x200.png',
  true,
  '2025-12-15T09:09:21.000Z'::timestamptz
)
