INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Una suite su ruote: ecco Aznom L’Epoque',
  'una-suite-su-ruote-ecco-aznom-lepoque',
  'Spostarsi su strada come se ci si trovasse all’interno di una suite, di una cabina armatoriale o di un jet privato: più che viaggiare, abitare . È questa la filosofia che ha guidato Aznom Automotive nella creazione di L’Epoque , concept car sviluppata con Camal Studio e ispirata alle grandi vetture ',
  '**UNA SUITE SU RUOTE**

Spostarsi su strada come se ci si trovasse all’interno di una suite, di una cabina armatoriale o di un jet privato: più che viaggiare, abitare. È questa la filosofia che ha guidato Aznom Automotive nella creazione di L’Epoque, concept car sviluppata con Camal Studio e ispirata alle grandi vetture con autista degli anni Venti e Trenta. Essa è ispirata alle grandi vetture da parata e ai coupé chauffeur-driven degli anni ’20 e ’30, reinterpretata con proporzioni e tecnologie del XXI secolo.

Un omaggio al linguaggio Art Déco e ai grandi carrozzieri del passato, reinterpretato in chiave contemporanea. Presentata come studio di stile con fattibilità teorica, L’Epoque non è al momento destinata alla produzione di serie, anche se Aznom non esclude la realizzazione di un esemplare unico o di una piccolissima serie su commissione.

Con una lunghezza che sfiora gli 8 metri e un’altezza prossima ai due, L’Epoque impone la propria presenza su strada come una vera architettura in movimento. Il lungo cofano, l’abitacolo arretrato e la coda affusolata di ispirazione nautica definiscono proporzioni volutamente esasperate.

La calandra frontale verticale richiama le grandi berline di rappresentanza del passato, mentre le luci LED verticali incastonate nei parafanghi emettono una calda tonalità color champagne. Al posteriore, una firma luminosa ad arco attraversa l’intera coda, fondendo minimalismo e modernismo.

Su L’EPOQUE l’esclusività non si misura in pollici di display, ma nella scelta dei materiali e nel pregio delle lavorazioni. Legno lavorato a mano, tessuti di pregio e dettagli tattili costruiscono un ambiente che privilegia sensazioni autentiche, non l’ostentazione tecnologica.

L’obiettivo è semplice da dire e difficile da progettare: eliminare la frattura tra la quiete di una suite (o di un ponte armatoriale, o di un jet) e il trasferimento su strada. L’EPOQUE nasce per rendere il tragitto una continuità dell’abitare.
![image](https://www.nolosubito.it/wp-content/uploads/2026/01/065705947-526cf0b3-8f43-44cc-b592-a9d9df9c31db-300x169.jpeg)
Le ruote da 30 pollici enfatizzano ulteriormente la maestosità del corpo vettura. Le portiere posteriori adottano un doppio cinematismo: una porzione del tetto si solleva e la porta si apre controvento, facilitando l’accesso.

L’abitacolo è concepito secondo una configurazione 2+2+2, ma Aznom evita volutamente il concetto di “sedili”. Gli interni sono pensati come arredi, con al centro dell’esperienza un grande divano posteriore, affiancato da sedute a scomparsa.

![image](https://www.nolosubito.it/wp-content/uploads/2026/01/859975-16x9-lg-300x169.jpeg) ![image](https://www.nolosubito.it/wp-content/uploads/2026/01/Aznom-LEpoque-12-300x162.webp) ![image](https://www.nolosubito.it/wp-content/uploads/2026/01/WGhnTyUdmZdmGPevDJsK-300x169.webp)![image](https://www.nolosubito.it/wp-content/uploads/2026/01/208B521-copia-300x148.webp)
L’obiettivo è creare una vera lounge privata, dove la tecnologia rimane invisibile fino al momento del bisogno. I materiali sono naturali e pregiati: legni selezionati, pelli e tessuti ispirati agli interni dei palazzi storici italiani, lavorati secondo tradizione artigianale. Il mobile centrale, definito “credenza tecnica”, può ospitare minibar refrigerato, vano sigari climatizzato, compartimenti per orologi automatici o altre soluzioni personalizzate. Un assistente basato su intelligenza artificiale gestisce clima, umidità, profumazione, illuminazione e atmosfere tramite comandi vocali naturali.

Sotto l’abito rétro-futurista si nasconde una piattaforma altamente moderna. L’Epoque è spinta da quattro motori elettrici, uno per ruota, per una potenza complessiva superiore ai 1.000 CV.

L’energia proviene da una batteria da 100 kWh, supportata da un motore V6 con funzione di range extender. Lo studio di fattibilità ipotizza un telaio a longheroni, trazione integrale intelligente e sospensioni attive capaci di leggere il manto stradale e livellare automaticamente la vettura.

![image](https://www.nolosubito.it/wp-content/uploads/2026/01/Aznom-LEpoque-300x171.webp)
L’Epoque non rientra in nessun segmento tradizionale: troppo lunga per essere una berlina, troppo bassa per essere un SUV. È una visione, un manifesto di ciò che Aznom immagina per il lusso del futuro.

Aznom, che deve il proprio nome a “Monza” scritto al contrario, realizza in Italia progetti su misura e concept visionari. E come già accaduto con la Palladium, anche questa visione potrebbe un giorno trasformarsi in realtà, se un cliente decidesse di commissionarla.

Di certo, L’Epoque dimostra che nel mondo dell’automobile c’è ancora spazio per sorprendere.

![image](https://www.nolosubito.it/wp-content/uploads/2026/01/2010B91-copia-300x169.webp)

Foto prese dal sito ufficiale ---> [https://www.aznomautomotive.com/aznom-epoque/](https://www.aznomautomotive.com/aznom-epoque/)
Video --> https://www.youtube.com/watch?v=dUSaBZd-uqM',
  'Notizie',
  'https://www.nolosubito.it/wp-content/uploads/2026/01/065705947-526cf0b3-8f43-44cc-b592-a9d9df9c31db-300x169.jpeg',
  true,
  '2026-01-29T14:08:57.000Z'::timestamptz
)
