INSERT INTO posts (title, slug, summary, content, category, cover_image_url, is_published, published_date) VALUES
(
  'Porsche: lo stop al progetto 718 elettrica',
  'porsche-lo-stop-al-progetto-718-elettrica',
  'Nel 2026 uno dei nomi più iconici del mondo delle auto sportive – la Porsche 718 , incarnata da modelli leggendari come Boxster e Cayman – si trova al centro di una discussione che potrebbe riscrivere il futuro della sportività a Zuffenhausen.',
  '**Porsche: lo stop al progetto 718 elettrica**
Nel 2026 uno dei nomi più iconici del mondo delle auto sportive – la Porsche 718, incarnata da modelli leggendari come Boxster e Cayman – si trova al centro di una discussione che potrebbe riscrivere il futuro della sportività a Zuffenhausen.

Secondo numerose fonti e indiscrezioni emerse nelle ultime settimane, Porsche sta valutando seriamente di fermare lo sviluppo delle versioni completamente elettriche della 718 che erano state annunciate e attese da anni. Questa eventuale cancellazione non è solo un’ipotesi isolata, ma una possibilità concreta sul tavolo della dirigenza, in particolare da quando il nuovo CEO Michael Leiters ha preso il comando dell’azienda all’inizio del 2026.

### Perché Porsche sta considerando lo stop?

Tre principali fattori stanno spingendo verso questa decisione:

Costi di sviluppo in forte crescita - Il progetto 718 elettrica ha incontrato numerose difficoltà tecniche e finanziarie. Lo sviluppo di una piattaforma sportiva elettrica con prestazioni all’altezza delle aspettative Porsche è risultato molto più costoso del previsto, con ritardi e spese che continuano ad aumentare.

Ritardi e difficoltà tecniche - Originariamente prevista per il 2026, la nuova 718 elettrica ha già subito vari rinvii legati, tra l’altro, a problemi nell’approvvigionamento di batterie ad alte prestazioni dopo il fallimento del fornitore Northvolt.

Contesto di mercato incerto - La domanda globale di auto elettriche, in particolare nel segmento delle sportive, non sta crescendo così rapidamente come alcune previsioni avevano ipotizzato. A ciò si aggiungono performance di vendita non ottimali in mercati chiave come la Cina e l’impatto di nuove tariffe negli USA, elementi che rendono ancora più delicato qualsiasi investimento massiccio in nuove tecnologie.

### Cosa significa per Boxster e Cayman

La 718 tradizionale con motore a combustione è stata eliminata da alcuni mercati nel 2025 a causa di nuove normative come quelle sulla cybersicurezza, che richiedevano aggiornamenti troppo costosi per una piattaforma che stava ormai finendo il suo ciclo di vita.

Il piano originario prevedeva di sostituire completamente questa generazione con versioni elettriche, mantenendo vivo il nome 718 anche in chiave moderna. Ora, però, quel piano rischia di saltare del tutto, con Porsche che potrebbe annullare il progetto elettrico prima ancora che arrivi in produzione.

### Cosa potrebbe accadere adesso

Le opzioni sul tavolo della Casa di Stoccarda non sono solo due estremi (“fare o non fare” la 718 elettrica), ma comprendono varie possibilità strategiche:

 	
Annullare del tutto il progetto EV, risparmiando risorse e concentrandosi su altri modelli più redditizi o con timeline più chiare.

 	
Riscrivere la strategia, puntando su versioni ibride o su una piattaforma mista che possa integrare motore termico e elettrico – sebbene questa soluzione richiederebbe comunque investimenti e tempo extra.

 	
Ritardare ulteriormente il lancio, mantenendo l’obiettivo EV ma cambiando tempistiche e priorità industriali.

La decisione definitiva non è stata ancora ufficializzata da Porsche, e per ora si basa su fonti vicine alle trattative interne. La casa automobilistica ha rifiutato di commentare pubblicamente queste speculazioni, mentre il dibattito interno prosegue.

La possibile cancellazione della 718 elettrica rappresenta uno dei più importanti punti di svolta nella storia recente di Porsche. Se confermata, potrebbe segnare un rallentamento significativo della strategia di elettrificazione pura nel segmento delle sportive e suggerire una maggiore prudenza nei prossimi anni.

Gli appassionati di Porsche e gli osservatori del mercato automotive dovranno continuare a seguire gli sviluppi, perché questa scelta potrebbe influenzare non solo il futuro della 718, ma l’intera visione del brand tedesco nei confronti dell’elettrico ad alte prestazioni.',
  'Notizie',
  '',
  true,
  '2026-02-05T12:44:13.000Z'::timestamptz
)
